--
-- Name: mri_container; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.mri_container AS
 SELECT a1.prr_nsid AS ns_id,
    a1.prr_id AS rsrc_container_id,
    a1.prr_oid AS ro_oid,
    a1.prr_typename AS ro_typename,
    a2.prd_attr_value AS creation_time,
    a3.prd_attr_value AS last_updated_time,
    a4.prd_attr_value AS created_by,
    a5.prd_attr_value AS last_modified_by,
    concat(concat(concat(a6.prd_attr_value, COALESCE(a7.prd_attr_value, ''::character varying)), COALESCE(a8.prd_attr_value, ''::character varying)), COALESCE(a9.prd_attr_value, ''::character varying)) AS object_name,
    a1.prr_parentcontainer AS parent_rsrc_container
   FROM ((((((((public.pr_resource a1
     LEFT JOIN public.pr_attribute a2 ON (((a1.prr_id = a2.pra_resource) AND ((a2.prd_attr_name)::text = 'REPO.SERVICE_PROP.UTC_CREATION_TIME_ATTR'::text))))
     LEFT JOIN public.pr_attribute a3 ON (((a1.prr_id = a3.pra_resource) AND ((a3.prd_attr_name)::text = 'REPO.SERVICE_PROP.UTC_LAST_UPDATED_TIME_ATTR'::text))))
     LEFT JOIN public.pr_attribute a4 ON (((a1.prr_id = a4.pra_resource) AND ((a4.prd_attr_name)::text = 'REPO.SERVICE_PROP.CREATED_BY_ATTR'::text))))
     LEFT JOIN public.pr_attribute a5 ON (((a1.prr_id = a5.pra_resource) AND ((a5.prd_attr_name)::text = 'REPO.SERVICE_PROP.LAST_MODIFIED_BY_ATTR'::text))))
     LEFT JOIN public.pr_attribute a6 ON (((a1.prr_id = a6.pra_resource) AND ((a6.prd_attr_name)::text = 'REPO.SYSTEM.PRS_ORIGINAL_OBJECT_NAME_ATTR'::text))))
     LEFT JOIN public.pr_attribute a7 ON (((a1.prr_id = a7.pra_resource) AND ((a7.prd_attr_name)::text = 'REPO.SYSTEM.PRS_ORIGINAL_OBJECT_NAME_ATTR_1'::text))))
     LEFT JOIN public.pr_attribute a8 ON (((a1.prr_id = a8.pra_resource) AND ((a8.prd_attr_name)::text = 'REPO.SYSTEM.PRS_ORIGINAL_OBJECT_NAME_ATTR_2'::text))))
     LEFT JOIN public.pr_attribute a9 ON (((a1.prr_id = a9.pra_resource) AND ((a9.prd_attr_name)::text = 'REPO.SYSTEM.PRS_ORIGINAL_OBJECT_NAME_ATTR_3'::text))));


