--
-- Name: rep_all_mappings; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_all_mappings AS
 SELECT opb_subject.subj_name AS parent_subject_area,
    opb_subject.subj_id AS parent_subject_id,
    opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    opb_mapping.mapping_name AS parent_mapping_name,
    opb_mapping.mapping_id AS parent_mapping_id,
    opb_mapping.version_number AS parent_mapping_version_number,
    opb_mapping.version_status AS parent_mapping_version_status,
    opb_mapping.utc_checkin AS parent_mapping_utc_checkin,
    opb_mapping.utc_last_saved AS parent_mapping_utc_last_saved,
    opb_mapping.last_saved AS parent_mapping_last_saved,
    opb_mapping.is_valid AS parent_mapping_is_valid,
    opb_mapping.comments AS parent_mapping_description,
    opb_mapping.mapping_name,
    opb_mapping.mapping_id,
    opb_mapping.version_number AS mapping_version_number,
    opb_mapping.version_status AS mapping_version_status,
    opb_mapping.utc_checkin AS mapping_utc_checkin,
    opb_mapping.utc_last_saved AS mapping_utc_last_saved,
    opb_mapping.last_saved AS mapping_last_saved,
    opb_mapping.comments AS mapping_description,
    NULL::text AS repository_name,
    0 AS is_global_shortcut,
    0 AS is_shortcut
   FROM public.opb_mapping,
    public.opb_subject
