CREATE VIEW public.rep_all_source_flds AS
 SELECT opb_subject.subj_name AS parent_subject_area,
    opb_subject.subj_id AS parent_subject_id,
    opb_src.source_name AS parent_source_name,
    opb_src.business_name AS parent_source_business_name,
    opb_src.src_id AS parent_source_id,
    opb_src.src_desc AS parent_source_description,
    opb_src.version_number AS parent_source_version_number,
    opb_src.version_status AS parent_source_version_status,
    opb_src.utc_checkin AS parent_source_utc_checkin,
    opb_src.utc_last_saved AS parent_source_utc_last_saved,
    opb_src.last_saved AS parent_source_last_saved,
    opb_dbd.srctype AS parent_source_type,
    opb_dbd.dbdnam AS parent_source_database_name,
    opb_mmd_dbtype.dbtype_name AS parent_source_database_type,
    opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    opb_src.source_name,
    opb_src.src_id AS source_id,
    opb_src.src_desc AS source_description,
    opb_src.version_number AS source_version_number,
    opb_src.version_status AS source_version_status,
    opb_src.utc_checkin AS source_utc_checkin,
    opb_src.utc_last_saved AS source_utc_last_saved,
    opb_src.last_saved AS source_last_saved,
    opb_dbd.dbdnam AS source_database_name,
    opb_src_fld.src_name AS source_field_name,
    opb_src_fld.business_name AS source_field_business_name,
    opb_src_fld.fldid AS source_field_id,
    opb_src_fld.src_desc AS source_field_description,
    opb_src_fld.fldno AS source_field_number,
    opb_src_fld.nxtsibid AS source_field_next_field_id,
    opb_src_fld.fldlvl AS source_field_level,
    opb_src_fld.pictxt AS source_field_picture_text,
    opb_src_fld.occtimes AS source_field_occurs_times,
    opb_src_fld.redfname AS source_field_redefines_field,
    opb_src_fld.offs AS source_field_display_offset,
    opb_src_fld.len AS source_field_display_length,
    opb_src_fld.poffs AS source_field_physical_offset,
    opb_src_fld.plen AS source_field_physical_length,
    opb_src_fld.nxtchldid AS source_field_child_field_id,
    rep_src_key_types.keytype_name AS source_field_key_type,
    rep_fld_datatype.dtype_name AS source_field_datatype,
    opb_picdsc.src_prec AS source_field_precision,
    opb_picdsc.src_scale AS source_field_scale,
    rep_pic_usage.usage_name AS source_field_pic_usage_name,
    opb_src_fld.nulltype AS source_field_nulltype,
    NULL::character varying AS repository_name,
    0 AS is_shortcut,
    0 AS is_global_shortcut
   FROM public.opb_subject,
    public.opb_src,
    public.opb_dbd,
    public.opb_mmd_dbtype,
    public.opb_src_fld,
    public.rep_fld_datatype,
    public.opb_picdsc,
    public.rep_src_key_types,
    public.rep_pic_usage
  WHERE ((opb_src.subj_id = opb_subject.subj_id) AND (opb_src.subj_id = opb_dbd.subj_id) AND (opb_src.src_id = opb_src_fld.src_id) AND (opb_src_fld.picid = opb_picdsc.picid) AND (opb_src_fld.keytype = rep_src_key_types.keytype_num) AND (opb_src.dbdid = opb_dbd.dbdid) AND (opb_dbd.dbtype = opb_mmd_dbtype.dbtype_id) AND (opb_src_fld.is_hidden = 0) AND (opb_picdsc.src_ntype = rep_fld_datatype.dtype_num) AND (opb_src.version_number = opb_dbd.version_number) AND (opb_src.version_number = opb_src_fld.version_number) AND (opb_src.version_number = opb_picdsc.version_number) AND (opb_src.is_visible = 1) AND (mod(opb_picdsc.pic_usage, 16) = rep_pic_usage.usage_num) AND (NOT (EXISTS ( SELECT '1'::text
           FROM public.opb_shortcut,
            public.opb_shortcut dbd
          WHERE ((opb_src.src_id = opb_shortcut.object_id) AND (opb_src.subj_id = opb_shortcut.subject_id) AND (opb_shortcut.object_type = 25) AND (opb_shortcut.is_visible = 1) AND (opb_shortcut.parent_id = dbd.object_id) AND (opb_shortcut.subject_id = dbd.subject_id) AND (opb_shortcut.version_number = dbd.version_number) AND (NOT ((opb_shortcut.shortcut_name)::text = (dbd.shortcut_name)::text)) AND (dbd.object_type = 22))))))
UNION ALL
 SELECT parent.subj_name AS parent_subject_area,
    parent.subj_id AS parent_subject_id,
    opb_src.source_name AS parent_source_name,
    opb_src.business_name AS parent_source_business_name,
    opb_src.src_id AS parent_source_id,
    opb_src.src_desc AS parent_source_description,
    opb_src.version_number AS parent_source_version_number,
    opb_src.version_status AS parent_source_version_status,
    opb_src.utc_checkin AS parent_source_utc_checkin,
    opb_src.utc_last_saved AS parent_source_utc_last_saved,
    opb_src.last_saved AS parent_source_last_saved,
    opb_dbd.srctype AS parent_source_type,
    opb_dbd.dbdnam AS parent_source_database_name,
    opb_mmd_dbtype.dbtype_name AS parent_source_database_type,
    child.subj_name AS subject_area,
    child.subj_id AS subject_id,
    opb_shortcut.shortcut_name AS source_name,
    opb_shortcut.object_id AS source_id,
    opb_shortcut.comments AS source_description,
    opb_shortcut.version_number AS source_version_number,
    opb_shortcut.version_status AS source_version_status,
    opb_shortcut.utc_checkin AS source_utc_checkin,
    opb_shortcut.utc_last_saved AS source_utc_last_saved,
    opb_shortcut.creation_time AS source_last_saved,
    dbd.shortcut_name AS source_database_name,
    opb_src_fld.src_name AS source_field_name,
    opb_src_fld.business_name AS source_field_business_name,
    opb_src_fld.fldid AS source_field_id,
    opb_src_fld.src_desc AS source_field_description,
    opb_src_fld.fldno AS source_field_number,
    opb_src_fld.nxtsibid AS source_field_next_field_id,
    opb_src_fld.fldlvl AS source_field_level,
    opb_src_fld.pictxt AS source_field_picture_text,
    opb_src_fld.occtimes AS source_field_occurs_times,
    opb_src_fld.redfname AS source_field_redefines_field,
    opb_src_fld.offs AS source_field_display_offset,
    opb_src_fld.len AS source_field_display_length,
    opb_src_fld.poffs AS source_field_physical_offset,
    opb_src_fld.plen AS source_field_physical_length,
    opb_src_fld.nxtchldid AS source_field_child_field_id,
    rep_src_key_types.keytype_name AS source_field_key_type,
    rep_fld_datatype.dtype_name AS source_field_datatype,
    opb_picdsc.src_prec AS source_field_precision,
    opb_picdsc.src_scale AS source_field_scale,
    rep_pic_usage.usage_name AS source_field_pic_usage_name,
    opb_src_fld.nulltype AS source_field_nulltype,
    opb_shortcut.repository_name,
    1 AS is_shortcut,
    0 AS is_global_shortcut
   FROM public.opb_shortcut,
    public.opb_subject parent,
    public.opb_subject child,
    public.opb_src,
    public.opb_dbd,
    public.opb_mmd_dbtype,
    public.opb_src_fld,
    public.rep_fld_datatype,
    public.opb_picdsc,
    public.rep_src_key_types,
    public.opb_shortcut dbd,
    public.rep_pic_usage
  WHERE ((opb_shortcut.object_id = opb_src.src_id) AND (opb_shortcut.subject_id = child.subj_id) AND (opb_shortcut.reference_type = 1) AND (opb_shortcut.is_visible = 1) AND (opb_shortcut.object_type = 25) AND (opb_src.subj_id = parent.subj_id) AND (opb_src.src_id = opb_src_fld.src_id) AND (opb_src.dbdid = opb_dbd.dbdid) AND (opb_src_fld.picid = opb_picdsc.picid) AND (opb_src_fld.keytype = rep_src_key_types.keytype_num) AND (opb_src_fld.is_hidden = 0) AND (opb_picdsc.src_ntype = rep_fld_datatype.dtype_num) AND (opb_dbd.dbtype = opb_mmd_dbtype.dbtype_id) AND (opb_src.version_number = opb_dbd.version_number) AND (opb_src.version_number = opb_src_fld.version_number) AND (opb_src.version_number = opb_picdsc.version_number) AND (opb_src.is_visible = 1) AND (mod(opb_picdsc.pic_usage, 16) = rep_pic_usage.usage_num) AND (opb_shortcut.parent_id = dbd.object_id) AND (opb_shortcut.subject_id = dbd.subject_id) AND (opb_shortcut.version_number = dbd.version_number) AND (NOT ((opb_shortcut.shortcut_name)::text = (dbd.shortcut_name)::text)) AND (dbd.object_type = 22))
UNION ALL
 SELECT NULL::character varying AS parent_subject_area,
