           FROM public.opb_shortcut,
            public.opb_shortcut dbd
          WHERE ((opb_src.src_id = opb_shortcut.object_id) AND (opb_src.subj_id = opb_shortcut.subject_id) AND (opb_shortcut.object_type = 25) AND (opb_shortcut.is_visible = 1) AND (opb_shortcut.parent_id = dbd.object_id) AND (opb_shortcut.subject_id = dbd.subject_id) AND (opb_shortcut.version_number = dbd.version_number) AND (NOT ((opb_shortcut.shortcut_name)::text = (dbd.shortcut_name)::text)) AND (dbd.object_type = 22))))))
