--
-- Name: rep_all_transforms; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_all_transforms AS
 SELECT opb_subject.subj_name AS parent_subject_area,
    opb_subject.subj_id AS parent_subject_id,
    opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    opb_widget.widget_name AS parent_widget_name,
    opb_widget.widget_id AS parent_widget_id,
    opb_widget.version_number AS parent_widget_version_number,
    opb_widget.version_status AS parent_widget_version_status,
    opb_widget.utc_checkin AS parent_widget_utc_checkin,
    opb_widget.utc_last_saved AS parent_widget_utc_last_saved,
    opb_widget.last_saved AS parent_widget_last_saved,
    opb_widget.is_reusable AS parent_widget_is_reusable,
    opb_widget.comments AS parent_widget_description,
    opb_widget.widget_name,
    opb_widget.widget_id,
    opb_widget.version_number AS widget_version_number,
    opb_widget.version_status AS widget_version_status,
    opb_widget.utc_checkin AS widget_utc_checkin,
    opb_widget.utc_last_saved AS widget_utc_last_saved,
    opb_widget.last_saved AS widget_last_saved,
    opb_widget.widget_type AS widget_type_id,
    opb_object_type.object_type_name AS widget_type_name,
    opb_widget.comments AS widget_description,
    NULL::character varying AS repository_name,
    0 AS is_global_shortcut,
    0 AS is_shortcut
   FROM public.opb_widget,
    public.opb_object_type,
    public.opb_subject
  WHERE ((opb_widget.widget_type = opb_object_type.object_type_id) AND (opb_widget.subject_id = opb_subject.subj_id) AND (opb_widget.widget_type <> 44) AND (opb_widget.is_visible = 1))
UNION ALL
 SELECT parent.subj_name AS parent_subject_area,
    parent.subj_id AS parent_subject_id,
    child.subj_name AS subject_area,
    child.subj_id AS subject_id,
    opb_widget.widget_name AS parent_widget_name,
    opb_widget.widget_id AS parent_widget_id,
    opb_widget.version_number AS parent_widget_version_number,
    opb_widget.version_status AS parent_widget_version_status,
    opb_widget.utc_checkin AS parent_widget_utc_checkin,
    opb_widget.utc_last_saved AS parent_widget_utc_last_saved,
    opb_widget.last_saved AS parent_widget_last_saved,
    opb_widget.is_reusable AS parent_widget_is_reusable,
    opb_widget.comments AS parent_widget_description,
    opb_shortcut.shortcut_name AS widget_name,
    opb_shortcut.object_id AS widget_id,
    opb_shortcut.version_number AS widget_version_number,
    opb_shortcut.version_status AS widget_version_status,
    opb_shortcut.utc_checkin AS widget_utc_checkin,
    opb_shortcut.utc_last_saved AS widget_utc_last_saved,
    opb_shortcut.creation_time AS widget_last_saved,
    opb_shortcut.object_subtype AS widget_type_id,
    opb_object_type.object_type_name AS widget_type_name,
    opb_shortcut.comments AS widget_description,
    opb_shortcut.repository_name,
    0 AS is_global_shortcut,
    1 AS is_shortcut
   FROM public.opb_widget,
    public.opb_shortcut,
    public.opb_object_type,
    public.opb_subject parent,
    public.opb_subject child
  WHERE ((opb_widget.widget_id = opb_shortcut.object_id) AND (opb_widget.subject_id = parent.subj_id) AND (opb_shortcut.subject_id = child.subj_id) AND (opb_shortcut.object_subtype = opb_object_type.object_type_id) AND (opb_shortcut.reference_type = 1) AND (opb_shortcut.object_type = 23) AND (opb_shortcut.is_visible = 1) AND (opb_widget.is_visible = 1))
UNION ALL
 SELECT NULL::character varying AS parent_subject_area,
    0 AS parent_subject_id,
    opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    NULL::character varying AS parent_widget_name,
    0 AS parent_widget_id,
    0 AS parent_widget_version_number,
    0 AS parent_widget_version_status,
    0 AS parent_widget_utc_checkin,
    0 AS parent_widget_utc_last_saved,
    NULL::character varying AS parent_widget_last_saved,
    9999999 AS parent_widget_is_reusable,
    NULL::character varying AS parent_widget_description,
    opb_shortcut.shortcut_name AS widget_name,
    opb_shortcut.object_id AS widget_id,
    opb_shortcut.version_number AS widget_version_number,
    opb_shortcut.version_status AS widget_version_status,
    opb_shortcut.utc_checkin AS widget_utc_checkin,
    opb_shortcut.utc_last_saved AS widget_utc_last_saved,
    opb_shortcut.creation_time AS widget_last_saved,
    opb_shortcut.object_subtype AS widget_type_id,
    opb_object_type.object_type_name AS widget_type_name,
    opb_shortcut.comments AS widget_description,
    opb_shortcut.repository_name,
    1 AS is_global_shortcut,
    1 AS is_shortcut
   FROM public.opb_shortcut,
    public.opb_object_type,
    public.opb_subject
  WHERE ((opb_shortcut.subject_id = opb_subject.subj_id) AND (opb_shortcut.object_subtype = opb_object_type.object_type_id) AND (opb_shortcut.reference_type = 2) AND (opb_shortcut.object_type = 23) AND (opb_shortcut.is_visible = 1));


