--
-- Name: rep_fld_mapping; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_fld_mapping AS
 SELECT opb_src_fld.src_name AS source_field_name,
    opb_src_fld.business_name AS src_fld_busname,
    opb_src.source_name,
    opb_src.business_name AS src_busname,
    opb_targ_fld.target_name AS target_column_name,
    opb_targ_fld.business_name AS targ_col_busname,
    opb_targ.target_name,
    opb_targ.business_name AS targ_busname,
    opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    opb_mapping.mapping_name,
    NULL::text AS version_id,
    NULL::text AS version_name,
    opb_targ_fld_expr.trans_expr AS trans_expression,
    opb_targ_fld_expr.user_comment,
    opb_targ_fld_expr.user_comment AS dba_comment,
    opb_mapping.comments AS mapping_comment,
    opb_mapping.last_saved AS mapping_last_saved,
    opb_mapping.version_number AS mapping_version_number,
    opb_src.version_number AS source_version_number,
    opb_targ.version_number AS target_version_number,
    opb_src.src_id AS source_id,
    opb_targ.target_id,
    opb_mapping.mapping_id
   FROM public.opb_subject,
    public.opb_mapping,
    public.opb_src,
    public.opb_src_fld,
    public.opb_targ,
    public.opb_targ_fld,
    public.opb_analyze_dep dependency,
    public.opb_widget_inst frominstances,
    public.opb_widget_inst toinstances,
    public.opb_targ_fld_expr
  WHERE ((opb_subject.subj_id = opb_mapping.subject_id) AND (opb_mapping.mapping_id = dependency.mapping_id) AND (opb_mapping.mapping_id = frominstances.mapping_id) AND (opb_mapping.mapping_id = toinstances.mapping_id) AND (dependency.mapping_id = frominstances.mapping_id) AND (dependency.mapping_id = toinstances.mapping_id) AND (opb_targ.target_id = toinstances.widget_id) AND (toinstances.widget_type = 2) AND (opb_targ_fld.target_id = opb_targ.target_id) AND (opb_targ_fld.fldid = dependency.to_field_id) AND (toinstances.instance_id = dependency.to_instance_id) AND (opb_src.src_id = frominstances.widget_id) AND (frominstances.widget_type = 1) AND (opb_src_fld.src_id = opb_src.src_id) AND (opb_src_fld.fldid = dependency.from_field_id) AND (frominstances.instance_id = dependency.from_instance_id) AND (opb_targ_fld_expr.mapping_id = toinstances.mapping_id) AND (opb_targ_fld_expr.target_inst_id = toinstances.instance_id) AND (opb_targ_fld_expr.target_fld = opb_targ_fld.fldid) AND (opb_src_fld.is_hidden = 0) AND (opb_mapping.ref_widget_id = 0) AND (opb_mapping.version_number = toinstances.version_number) AND (opb_mapping.version_number = frominstances.version_number) AND (opb_mapping.version_number = dependency.version_number) AND (opb_mapping.version_number = opb_targ_fld_expr.version_number) AND (opb_src.version_number = opb_src_fld.version_number) AND (opb_targ.version_number = opb_targ_fld.version_number) AND (opb_mapping.is_visible = 1) AND (opb_src.is_visible = 1) AND (opb_targ.is_visible = 1));


ALTER TABLE public.rep_fld_mapping OWNER TO infa;

