--
-- Name: rep_load_sessions; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_load_sessions AS
 SELECT opb_subject.subj_name AS subject_area,
    opb_task.task_name AS session_name,
    opb_task.last_saved,
    opb_session.session_id,
    opb_mapping.mapping_name,
    0 AS version_id,
    NULL::text AS version_name,
    0 AS is_active,
    NULL::text AS starttime,
    0 AS sess_interval,
    0 AS repeat_count,
    NULL::text AS session_log_file,
    NULL::text AS bad_file_location,
    0 AS target_id,
    0 AS source_id,
    opb_task.version_number AS session_version_number,
    opb_mapping.version_number AS mapping_version_number,
    opb_subject.subj_id AS subject_id,
    opb_task.saved_valid AS is_valid,
    opb_task.is_reusable,
    opb_task.comments,
    opb_mapping.mapping_id,
    1 AS is_impacted
   FROM public.opb_task,
    public.opb_mapping,
    public.opb_session,
    public.opb_subject
  WHERE ((opb_task.subject_id = opb_subject.subj_id) AND (opb_task.task_type = 68) AND (opb_task.task_id = opb_session.session_id) AND (opb_mapping.mapping_id = opb_session.mapping_id) AND (opb_task.version_number = opb_session.version_number) AND (opb_task.is_visible = 1) AND (opb_mapping.is_visible = 1) AND ((opb_task.is_invalidated = 1) OR (EXISTS ( SELECT v.subject_id,
            v.object_id,
            v.object_type,
            v.version_number,
            v.inv_utc,
            v.inv_type,
            v.inv_comments,
            v.line_no
           FROM public.opb_validate v
          WHERE ((v.subject_id = opb_mapping.subject_id) AND (v.object_type = 21) AND (v.object_id = opb_mapping.mapping_id) AND (v.version_number = opb_mapping.version_number) AND (v.inv_utc > opb_task.utc_last_saved)))) OR (EXISTS ( SELECT c.workflow_id,
            c.task_id,
            c.task_inst_id,
            c.ref_obj_id,
            c.ref_obj_type,
            c.object_type,
            c.object_seq_type,
            c.opb_object_id,
            c.version_number,
            c.ref_version_number,
            t.subject_id,
            t.task_id,
            t.task_type,
            t.task_name,
            t.task_property,
            t.is_reusable,
            t.is_valid,
            t.is_enabled,
            t.comments,
            t.last_saved,
            t.create_info,
            t.opb_object_id,
            t.objversion,
            t.version_number,
            t.utc_last_saved,
            t.is_visible,
            t.checkout_user_id,
            t.version_status,
            t.is_marked,
            t.utc_ref_time,
            t.utc_checkin,
            t.saved_valid,
            t.is_invalidated,
            t.ru_parent_id,
            t.ru_version_number,
            t.obj_cmp,
            v.subject_id,
            v.object_id,
            v.object_type,
            v.version_number,
            v.inv_utc,
            v.inv_type,
            v.inv_comments,
            v.line_no
           FROM public.opb_component c,
            public.opb_task t,
            public.opb_validate v
          WHERE ((c.workflow_id = 0) AND (c.task_id = opb_task.task_id) AND (c.version_number = opb_task.version_number) AND (t.task_type = c.object_type) AND (t.task_id = c.ref_obj_id) AND (t.is_visible <> 2) AND (v.object_type = t.task_type) AND (v.object_id = t.task_id) AND (v.version_number = t.version_number) AND (v.inv_utc > opb_task.utc_last_saved)))) OR (EXISTS ( SELECT c.workflow_id,
            c.task_id,
            c.task_inst_id,
            c.ref_obj_id,
            c.ref_obj_type,
            c.object_type,
            c.object_seq_type,
            c.opb_object_id,
            c.version_number,
            c.ref_version_number,
            g.subject_id,
            g.config_id,
            g.config_type,
            g.config_name,
            g.comments,
            g.create_info,
            g.last_saved,
            g.is_default,
            g.opb_object_id,
            g.objversion,
            g.version_number,
            g.utc_last_saved,
            g.is_visible,
            g.checkout_user_id,
            g.version_status,
            g.is_marked,
            g.utc_ref_time,
            g.utc_checkin,
            g.obj_cmp,
            v.subject_id,
            v.object_id,
            v.object_type,
            v.version_number,
            v.inv_utc,
            v.inv_type,
            v.inv_comments,
            v.line_no
           FROM public.opb_component c,
            public.opb_session_config g,
            public.opb_validate v
          WHERE ((c.workflow_id = 0) AND (c.task_id = opb_task.task_id) AND (c.version_number = opb_task.version_number) AND (c.object_type = 72) AND (g.config_id = c.ref_obj_id) AND (g.is_visible <> 2) AND (v.object_type = 72) AND (v.object_id = g.config_id) AND (v.version_number = g.version_number) AND (v.inv_utc > opb_task.utc_last_saved)))) OR (EXISTS ( SELECT v.subject_id,
            v.object_id,
            v.object_type,
            v.version_number,
            v.inv_utc,
            v.inv_type,
            v.inv_comments,
            v.line_no,
            i.mapping_id,
            i.widget_id,
            i.widget_type,
            i.instance_id,
            i.instance_name,
            i.comments,
            i.widget_prop,
            i.version_number,
            i.ref_version_number,
            r.src_id,
            r.subj_id,
            r.file_name,
            r.source_name,
            r.business_name,
            r.selid,
            r.target_id,
            r.fdsiz,
            r.nxtfdid,
            r.bestfdid,
            r.fldid,
            r.recnam,
            r.nxtsibid,
            r.nxtchldid,
            r.parentid,
            r.dbdid,
            r.pfdsiz,
            r.pfdsiz_min,
