--
-- Name: rep_src_file_flds; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_src_file_flds AS
 SELECT opb_src_fld.fldid AS field_id,
    opb_subject.subj_name AS subject_area,
    opb_src_fld.src_id AS file_id,
    opb_src_fld.src_name AS field_name,
    opb_src_fld.fldlvl AS field_level,
    opb_src_fld.fldno AS field_number,
    opb_src_fld.src_desc AS field_description,
    opb_src_fld.pictxt AS picture_text,
    opb_src_fld.occtimes AS occurs,
    opb_src_fld.redfname AS redefines_field,
    rep_src_key_types.keytype_name AS key_type,
    opb_src_fld.offs AS display_offset,
    opb_src_fld.len AS display_length,
    opb_src_fld.poffs AS physical_offset,
    opb_src_fld.plen AS physical_length,
    rep_pic_usage.usage_name AS usage_type,
    opb_picdsc.src_prec AS data_precision,
    opb_picdsc.src_scale AS data_scale,
    opb_src_fld.nxtchldid AS child_id,
    opb_src_fld.nxtsibid AS sibling_id,
    NULL::text AS version_id,
    opb_src.version_number AS src_version_number
   FROM public.opb_src,
    public.opb_src_fld,
    public.rep_pic_usage,
    public.opb_picdsc,
    public.opb_subject,
    public.rep_src_key_types,
    public.opb_dbd,
    public.opb_mmd_dbtype
  WHERE ((opb_subject.subj_id = opb_src.subj_id) AND (opb_src.subj_id = opb_dbd.subj_id) AND (opb_src_fld.picid = opb_picdsc.picid) AND (mod(opb_picdsc.pic_usage, 16) = rep_pic_usage.usage_num) AND (opb_src.src_id = opb_src_fld.src_id) AND (opb_src_fld.keytype = rep_src_key_types.keytype_num) AND ((opb_src.file_name)::text <> '$EXPORTED'::text) AND (opb_src.dbdid = opb_dbd.dbdid) AND (opb_dbd.dbtype = opb_mmd_dbtype.dbtype_id) AND (opb_dbd.srctype = 1) AND (opb_src_fld.is_hidden = 0) AND (opb_src.version_number = opb_dbd.version_number) AND (opb_src.version_number = opb_picdsc.version_number) AND (opb_src.version_number = opb_src_fld.version_number) AND (opb_src.is_visible = 1));


ALTER TABLE public.rep_src_file_flds OWNER TO infa;

