--
-- Name: rep_sess_config_parm; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_sess_config_parm AS
 SELECT opb_cfg_attr.session_id,
    opb_task.version_number AS session_version_number,
    opb_session_config.config_id,
    opb_cfg_attr.attr_id,
    opb_mmd_cfg_attr.attr_type,
    opb_mmd_cfg_attr.attr_name,
    opb_cfg_attr.attr_value
   FROM public.opb_cfg_attr,
    public.opb_mmd_cfg_attr,
    public.opb_task,
    public.opb_session_config,
    public.opb_component
  WHERE ((opb_cfg_attr.attr_id = opb_mmd_cfg_attr.attr_id) AND (opb_cfg_attr.session_id > 0) AND (opb_cfg_attr.workflow_id = 0) AND (opb_cfg_attr.attr_id <> ALL (ARRAY[1, 101, 201])) AND (opb_cfg_attr.session_id = opb_task.task_id) AND (opb_cfg_attr.version_number = opb_task.version_number) AND (opb_task.task_type = 68) AND (opb_task.is_visible = 1) AND (opb_cfg_attr.session_id = opb_component.task_id) AND (opb_component.object_type = 72) AND (opb_component.workflow_id = 0) AND (opb_component.task_inst_id = 0) AND (opb_component.task_id = opb_task.task_id) AND (opb_component.version_number = opb_task.version_number) AND (opb_component.ref_obj_id = opb_session_config.config_id) AND (opb_session_config.is_visible = 1))
UNION ALL
 SELECT opb_task.task_id AS session_id,
    opb_task.version_number AS session_version_number,
    opb_cfg_attr.config_id,
    opb_cfg_attr.attr_id,
    opb_mmd_cfg_attr.attr_type,
    opb_mmd_cfg_attr.attr_name,
    opb_cfg_attr.attr_value
   FROM public.opb_task,
    public.opb_cfg_attr,
    public.opb_mmd_cfg_attr,
    public.opb_session_config,
    public.opb_component
  WHERE ((opb_cfg_attr.attr_id = opb_mmd_cfg_attr.attr_id) AND (opb_cfg_attr.session_id = 0) AND (opb_cfg_attr.workflow_id = 0) AND (opb_cfg_attr.attr_id <> ALL (ARRAY[1, 101, 201])) AND (opb_task.task_type = 68) AND (opb_task.is_visible = 1) AND (opb_cfg_attr.config_id IN ( SELECT c.config_id
           FROM public.opb_cfg_attr a,
            public.opb_component b,
            public.opb_session_config c
          WHERE ((a.session_id > 0) AND (a.workflow_id = 0) AND (a.attr_id <> ALL (ARRAY[1, 101, 201])) AND (a.session_id = opb_task.task_id) AND (a.version_number = opb_task.version_number) AND (a.session_id = b.task_id) AND (b.object_type = 72) AND (b.workflow_id = 0) AND (b.task_inst_id = 0) AND (b.version_number = opb_task.version_number) AND (b.ref_obj_id = c.config_id) AND (c.is_visible = 1)))) AND (NOT (opb_cfg_attr.attr_id IN ( SELECT a.attr_id
           FROM public.opb_cfg_attr a,
            public.opb_component b,
            public.opb_session_config c
          WHERE ((a.session_id > 0) AND (a.workflow_id = 0) AND (a.attr_id <> ALL (ARRAY[1, 101, 201])) AND (a.session_id = opb_task.task_id) AND (a.version_number = opb_task.version_number) AND (a.session_id = b.task_id) AND (b.object_type = 72) AND (b.workflow_id = 0) AND (b.task_inst_id = 0) AND (b.version_number = opb_task.version_number) AND (b.ref_obj_id = c.config_id) AND (c.is_visible = 1))))) AND (opb_component.object_type = 72) AND (opb_component.task_id = opb_task.task_id) AND (opb_component.version_number = opb_task.version_number) AND (opb_component.ref_obj_id = opb_session_config.config_id) AND (opb_cfg_attr.config_id = opb_session_config.config_id) AND (opb_cfg_attr.version_number = opb_session_config.version_number) AND (opb_session_config.is_visible = 1))
UNION ALL
 SELECT opb_cfg_attr.session_id,
    0 AS session_version_number,
    opb_cfg_attr.config_id,
    opb_cfg_attr.attr_id,
    opb_mmd_cfg_attr.attr_type,
    opb_mmd_cfg_attr.attr_name,
    opb_cfg_attr.attr_value
   FROM public.opb_task,
    public.opb_cfg_attr,
    public.opb_mmd_cfg_attr,
    public.opb_session_config,
    public.opb_component
  WHERE ((opb_cfg_attr.attr_id = opb_mmd_cfg_attr.attr_id) AND (opb_cfg_attr.session_id = 0) AND (opb_cfg_attr.workflow_id = 0) AND (opb_cfg_attr.attr_id <> ALL (ARRAY[1, 101, 201])) AND (opb_task.task_type = 68) AND (opb_task.is_visible = 1) AND (opb_cfg_attr.config_id IN ( SELECT c.config_id
           FROM public.opb_cfg_attr a,
            public.opb_component b,
            public.opb_session_config c
          WHERE ((a.session_id > 0) AND (a.workflow_id = 0) AND (a.attr_id <> ALL (ARRAY[1, 101, 201])) AND (a.session_id = opb_task.task_id) AND (a.version_number = opb_task.version_number) AND (a.session_id = b.task_id) AND (b.object_type = 72) AND (b.workflow_id = 0) AND (b.task_inst_id = 0) AND (b.version_number = opb_task.version_number) AND (b.ref_obj_id = c.config_id) AND (c.is_visible = 1)))) AND (opb_cfg_attr.attr_id IN ( SELECT a.attr_id
           FROM public.opb_cfg_attr a,
            public.opb_component b,
            public.opb_session_config c
          WHERE ((a.session_id > 0) AND (a.workflow_id = 0) AND (a.attr_id <> ALL (ARRAY[1, 101, 201])) AND (a.session_id = opb_task.task_id) AND (a.version_number = opb_task.version_number) AND (a.session_id = b.task_id) AND (b.object_type = 72) AND (b.workflow_id = 0) AND (b.task_inst_id = 0) AND (b.version_number = opb_task.version_number) AND (b.ref_obj_id = c.config_id) AND (c.is_visible = 1)))) AND (opb_component.object_type = 72) AND (opb_component.task_id = opb_task.task_id) AND (opb_component.version_number = opb_task.version_number) AND (opb_component.ref_obj_id = opb_session_config.config_id) AND (opb_cfg_attr.config_id = opb_session_config.config_id) AND (opb_cfg_attr.version_number = opb_session_config.version_number) AND (opb_session_config.is_visible = 1))
UNION ALL
 SELECT opb_task.task_id AS session_id,
    opb_task.version_number AS session_version_number,
    opb_cfg_attr.config_id,
    opb_cfg_attr.attr_id,
    opb_mmd_cfg_attr.attr_type,
    opb_mmd_cfg_attr.attr_name,
    opb_cfg_attr.attr_value
   FROM public.opb_task,
    public.opb_cfg_attr,
    public.opb_mmd_cfg_attr,
    public.opb_session_config,
    public.opb_component
  WHERE ((opb_cfg_attr.attr_id = opb_mmd_cfg_attr.attr_id) AND (opb_cfg_attr.session_id = 0) AND (opb_cfg_attr.workflow_id = 0) AND (opb_cfg_attr.attr_id <> ALL (ARRAY[1, 101, 201])) AND (opb_task.task_type = 68) AND (opb_task.is_visible = 1) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_cfg_attr a,
            public.opb_component b,
            public.opb_session_config c
          WHERE ((a.session_id > 0) AND (a.workflow_id = 0) AND (a.attr_id <> ALL (ARRAY[1, 101, 201])) AND (a.session_id = opb_task.task_id) AND (a.version_number = opb_task.version_number) AND (a.session_id = b.task_id) AND (b.object_type = 72) AND (b.workflow_id = 0) AND (b.task_inst_id = 0) AND (b.version_number = opb_task.version_number) AND (b.ref_obj_id = c.config_id) AND (c.is_visible = 1))))) AND (opb_component.object_type = 72) AND (opb_component.task_id = opb_task.task_id) AND (opb_component.version_number = opb_task.version_number) AND (opb_component.ref_obj_id = opb_session_config.config_id) AND (opb_cfg_attr.config_id = opb_session_config.config_id) AND (opb_cfg_attr.version_number = opb_session_config.version_number) AND (opb_task.subject_id = opb_session_config.subject_id) AND (opb_session_config.is_visible = 1));


ALTER TABLE public.rep_sess_config_parm OWNER TO infa;

--
-- Name: rep_sess_inst_config_parm; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_sess_inst_config_parm AS
 SELECT opb_cfg_attr.workflow_id,
    opb_cfg_attr.session_id,
