   FROM public.opb_cfg_attr,
    public.opb_mmd_cfg_attr,
    public.opb_task,
    public.opb_task t1,
    public.opb_session_config,
    public.opb_component
  WHERE ((opb_cfg_attr.attr_id = opb_mmd_cfg_attr.attr_id) AND (opb_cfg_attr.session_id > 0) AND (opb_cfg_attr.workflow_id > 0) AND (opb_cfg_attr.attr_id <> ALL (ARRAY[1, 101, 201])) AND (opb_cfg_attr.workflow_id = opb_task.task_id) AND (opb_cfg_attr.version_number = opb_task.version_number) AND (opb_task.task_type = 71) AND (opb_task.is_visible = 1) AND (opb_cfg_attr.session_id = t1.task_id) AND (t1.task_type = 68) AND (t1.is_visible = 1) AND (opb_cfg_attr.session_id = opb_component.task_id) AND (opb_component.object_type = 72) AND (opb_component.workflow_id = 0) AND (opb_component.task_inst_id = 0) AND (opb_component.version_number = t1.version_number) AND (opb_component.ref_obj_id = opb_session_config.config_id) AND (opb_session_config.is_visible = 1));


ALTER TABLE public.rep_sess_inst_config_parm OWNER TO infa;

--
-- Name: rep_sess_log; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_sess_log AS
 SELECT opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    opb_task_inst_run.task_name AS session_name,
    opb_task_inst_run.task_id AS session_id,
    opb_task_inst_run.instance_name AS session_instance_name,
    opb_sess_task_log.targ_success_rows AS successful_rows,
    opb_sess_task_log.targ_failed_rows AS failed_rows,
    opb_sess_task_log.src_success_rows AS successful_source_rows,
    opb_sess_task_log.src_failed_rows AS failed_source_rows,
    opb_sess_task_log.first_error_code,
    opb_sess_task_log.first_error_msg,
    opb_task_inst_run.run_err_code AS last_error_code,
    opb_task_inst_run.run_err_msg AS last_error,
    opb_task_inst_run.run_status_code,
    opb_task_inst_run.start_time AS actual_start,
    opb_task_inst_run.end_time AS session_timestamp,
    opb_sess_task_log.log_file AS session_log_file,
    opb_sess_task_log.error_log_file AS bad_file_location,
    opb_task_inst_run.version_number AS task_version_number,
    opb_wflow_run.version_number AS workflow_version_number,
    opb_wflow_run.workflow_name,
    opb_sess_task_log.mapping_name,
    opb_sess_task_log.total_trans_errs AS total_err,
    opb_sess_task_log.workflow_id,
    opb_sess_task_log.workflow_run_id,
    opb_sess_task_log.worklet_run_id,
    opb_sess_task_log.instance_id
   FROM public.opb_task_inst_run,
    public.opb_sess_task_log,
    public.opb_wflow_run,
    public.opb_subject
  WHERE ((opb_task_inst_run.subject_id = opb_subject.subj_id) AND (opb_task_inst_run.workflow_id = opb_sess_task_log.workflow_id) AND (opb_task_inst_run.workflow_run_id = opb_sess_task_log.workflow_run_id) AND (opb_task_inst_run.worklet_run_id = opb_sess_task_log.worklet_run_id) AND (opb_task_inst_run.instance_id = opb_sess_task_log.instance_id) AND (opb_wflow_run.workflow_run_id = opb_sess_task_log.workflow_run_id) AND (opb_wflow_run.subject_id = opb_subject.subj_id));


ALTER TABLE public.rep_sess_log OWNER TO infa;

