  WHERE ((opb_partition_def.session_id = opb_swidget_inst.session_id) AND (opb_partition_def.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (opb_object_type.object_type_id = opb_swidget_inst.widget_type) AND (opb_partition_def.version_number = opb_swidget_inst.version_number) AND (opb_swidget_inst.version_number = opb_task.version_number) AND (opb_swidget_inst.session_id = opb_task.task_id) AND (opb_task.task_type = 68) AND (opb_task.is_visible = 1));


ALTER TABLE public.rep_sess_partition_def OWNER TO infa;

--
-- Name: rep_sess_tbl_log; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.rep_sess_tbl_log AS
 SELECT opb_subject.subj_name AS subject_area,
    opb_subject.subj_id AS subject_id,
    b.task_name AS session_name,
    b.task_id AS session_id,
    opb_task_inst.instance_name AS session_instance_name,
    opb_task_inst.instance_id AS session_instance_id,
    opb_task_inst.workflow_id,
    a.version_number AS workflow_version_number,
    opb_targ.target_name AS table_name,
    opb_targ.target_id AS table_id,
    opb_targ.version_number AS table_version_number,
    opb_targ.business_name AS table_busname,
    opb_swidginst_log.instance_name AS table_instance_name,
    opb_swidginst_log.applied_rows AS successful_rows,
    opb_swidginst_log.affected_rows AS successful_affected_rows,
    opb_swidginst_log.rejected_rows AS failed_rows,
    opb_swidginst_log.last_err_msg AS last_error,
    opb_swidginst_log.last_err_code AS last_error_code,
    opb_swidginst_log.start_time,
    opb_swidginst_log.end_time,
    NULL::text AS session_timestamp,
    ((attrdir.attr_value)::text || (attrfile.attr_value)::text) AS bad_file_location,
    b.version_number AS session_version_number,
    opb_swidginst_log.partition_name,
    opb_swidginst_log.mapplet_inst_name AS mapplet_instance_name,
    opb_swidginst_log.widget_name,
    opb_object_type.object_type_name AS type_name,
    opb_swidginst_log.group_name,
    opb_swidginst_log.thruput AS throughput,
    opb_swidginst_log.widget_type AS type_id
   FROM public.opb_swidginst_log,
    public.opb_subject,
    public.opb_task_inst,
    public.opb_swidget_inst,
    public.opb_targ,
    public.opb_task a,
    public.opb_task b,
    public.opb_object_type,
    public.opb_extn_attr attrdir,
    public.opb_extn_attr attrfile,
