    opb_mapping.last_saved AS mapping_last_saved,
    opb_mapping.version_number AS mapping_version_number,
    opb_targ.version_number AS target_version_number
   FROM public.opb_subject,
    public.opb_mapping,
    public.opb_targ,
    public.opb_targ_fld,
    public.opb_tds,
    public.opb_widget_inst,
    public.opb_widget_dep
  WHERE ((opb_targ_fld.target_id = opb_targ.target_id) AND (opb_tds.mapping_id = opb_mapping.mapping_id) AND (opb_mapping.mapping_id = opb_widget_inst.mapping_id) AND (opb_widget_inst.widget_type = 2) AND (opb_widget_inst.widget_id = opb_targ.target_id) AND (opb_tds.target_instance_id = opb_widget_inst.instance_id) AND (opb_widget_dep.mapping_id = opb_mapping.mapping_id) AND (opb_widget_dep.to_instance_id = opb_widget_inst.instance_id) AND (opb_widget_dep.to_field_id = opb_targ_fld.fldid) AND (opb_targ.subj_id = opb_subject.subj_id) AND (opb_mapping.ref_widget_id = 0) AND (opb_mapping.version_number = opb_widget_inst.version_number) AND (opb_mapping.version_number = opb_tds.version_number) AND (opb_mapping.version_number = opb_widget_dep.version_number) AND (opb_targ.version_number = opb_targ_fld.version_number) AND (opb_mapping.is_visible = 1) AND (opb_targ.is_visible = 1) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_targ_fld_expr
          WHERE ((opb_targ_fld_expr.mapping_id = opb_widget_inst.mapping_id) AND (opb_targ_fld_expr.target_inst_id = opb_widget_inst.instance_id) AND (opb_targ_fld_expr.target_fld = opb_targ_fld.fldid) AND (opb_mapping.version_number = opb_targ_fld_expr.version_number))))));


