--
-- Name: v_asc_cmd_cmdline; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_asc_cmd_cmdline AS
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.process.Command'::text AS from_class_id,
    ('Command_'::text || ltrim(((tasks.task_id)::character varying)::text)) AS from_element_id,
    ' '::text AS from_repo_id,
    'com.informatica.powercenter.process.CommandLine'::text AS to_class_id,
    ((((('CommandLine_'::text || ltrim(((tasks.task_id)::character varying)::text)) || '~'::text) || ltrim(((tval.instance_id)::character varying)::text)) || '~'::text) || ltrim(((tval.exec_order)::character varying)::text)) AS to_element_id,
    ' '::text AS to_repo_id,
    'org.omg.cwm.objectmodel.core.ClassifierFeature'::text AS association_id,
    tval.exec_order AS association_seq,
    'N'::text AS hidden_flag,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    tasks.subject_id AS src_subject_id,
    tasks.subject_id AS tgt_subject_id
   FROM public.opb_task tasks,
    public.opb_task_val_list tval
  WHERE ((tasks.task_type = 58) AND (tasks.task_id = tval.task_id) AND (tasks.task_type = tval.task_type) AND (tasks.version_number = tval.version_number) AND (tval.line_no = 1) AND (tasks.is_visible = 1) AND (tasks.is_reusable = 1) AND (tval.session_id = 0) AND (tval.instance_id = 0))
UNION ALL
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.process.CommandTaskInstance'::text AS from_class_id,
    ('TASK_INSTANCE_Command_'::text || ltrim(((tval.instance_id)::character varying)::text)) AS from_element_id,
    ' '::text AS from_repo_id,
    'com.informatica.powercenter.process.CommandLine'::text AS to_class_id,
    ((((('CommandLine_'::text || ltrim(((tval.task_id)::character varying)::text)) || '~'::text) || ltrim(((tval.instance_id)::character varying)::text)) || '~'::text) || ltrim(((tval.exec_order)::character varying)::text)) AS to_element_id,
    ' '::text AS to_repo_id,
    'org.omg.cwm.objectmodel.core.ClassifierFeature'::text AS association_id,
    tval.exec_order AS association_seq,
    'N'::text AS hidden_flag,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    wflow.subject_id AS src_subject_id,
    wflow.subject_id AS tgt_subject_id
   FROM public.opb_task wflow,
    public.opb_task_inst tinst,
    public.opb_task_val_list tval
  WHERE ((tval.task_type = 58) AND (tinst.instance_id = tval.instance_id) AND (tval.task_type = tinst.task_type) AND (tval.workflow_id = wflow.task_id) AND (tinst.version_number = tval.version_number) AND (wflow.version_number = tval.version_number) AND (tval.line_no = 1) AND (wflow.is_visible = 1))
UNION ALL
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.process.CommandTaskInstance'::text AS from_class_id,
    ('TASK_INSTANCE_Command_'::text || ltrim(((tinst.instance_id)::character varying)::text)) AS from_element_id,
    ' '::text AS from_repo_id,
    'com.informatica.powercenter.process.CommandLine'::text AS to_class_id,
    ((((('CommandLine_'::text || ltrim(((tval.task_id)::character varying)::text)) || '~'::text) || ltrim(((tval.instance_id)::character varying)::text)) || '~'::text) || ltrim(((tval.exec_order)::character varying)::text)) AS to_element_id,
    ' '::text AS to_repo_id,
    'org.omg.cwm.objectmodel.core.ClassifierFeature'::text AS association_id,
    tval.exec_order AS association_seq,
    'N'::text AS hidden_flag,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    wflow.subject_id AS src_subject_id,
    wflow.subject_id AS tgt_subject_id
   FROM public.opb_task wflow,
    public.opb_task tasks,
    public.opb_task_inst tinst,
    public.opb_task_val_list tval
  WHERE ((tval.task_type = 58) AND (tinst.task_id = tval.task_id) AND (tval.task_type = tinst.task_type) AND (tinst.workflow_id = wflow.task_id) AND (tinst.version_number = wflow.version_number) AND (wflow.is_visible = 1) AND (tval.task_id = tasks.task_id) AND (tasks.version_number = tval.version_number) AND (tval.line_no = 1) AND (tasks.is_visible = 1) AND (tasks.is_reusable = 0));


