--

CREATE VIEW public.v_asc_fldr_map AS
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.package.Folder'::text AS from_class_id,
    ('Folder_'::text || ltrim(((subj.subj_id)::character varying)::text)) AS from_element_id,
    ' '::text AS from_repo_id,
    'com.informatica.powercenter.map.Mapping'::text AS to_class_id,
    ('Mapping_'::text || ltrim(((mapping.mapping_id)::character varying)::text)) AS to_element_id,
    ' '::text AS to_repo_id,
    'org.omg.cwm.objectmodel.core.ElementOwnership'::text AS association_id,
    1 AS association_seq,
    'N'::text AS hidden_flag,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    subj.subj_id AS src_subject_id,
    subj.subj_id AS tgt_subject_id
   FROM public.opb_mapping mapping,
    public.opb_subject subj
  WHERE ((mapping.ref_widget_id = 0) AND (subj.subj_id = mapping.subject_id) AND (mapping.is_visible = 1));


