CREATE VIEW public.v_attribute_srcfld AS
 SELECT ''::text AS repository_id,
    'com.informatica.powercenter.map.SourceDefinitionPort'::text AS element_class_id,
    ((((('Source Definition'::text || '_'::text) || 'Field_'::text) || ltrim(((srcfld.src_id)::character varying)::text)) || '_'::text) || ltrim(((srcfld.fldid)::character varying)::text)) AS element_id,
    'GLOBAL'::text AS scope_type,
    'dataType'::text AS elmnt_attr_name,
        CASE
            WHEN (dtype1.dtype_name IS NOT NULL) THEN dtype1.dtype_name
            ELSE dtype2.dtype_name
        END AS elmnt_attr_value,
    ''::text AS elmnt_attr_desc,
    ''::text AS data_type,
    ''::text AS src_create_dt,
    src.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    src.subj_id AS subject_id
   FROM public.opb_src src,
    public.opb_src_fld srcfld,
    ((public.opb_picdsc picdsc
     LEFT JOIN public.rep_fld_datatype dtype1 ON ((dtype1.dtype_num = picdsc.src_ntype)))
     LEFT JOIN public.rep_fld_datatype dtype2 ON ((dtype2.dtype_num = picdsc.src_type)))
  WHERE ((src.src_id = srcfld.src_id) AND (src.version_number = srcfld.version_number) AND (src.is_visible = 1) AND (srcfld.picid = picdsc.picid) AND (srcfld.version_number = picdsc.version_number))
UNION ALL
