    'GLOBAL'::text AS scope_type,
    'precision'::text AS elmnt_attr_name,
    ltrim(((picdsc.src_prec)::character varying)::text) AS elmnt_attr_value,
    ''::text AS elmnt_attr_desc,
    ''::text AS data_type,
    ''::text AS src_create_dt,
    src.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
