--
-- Name: v_attribute_task; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_attribute_task AS
 SELECT ''::text AS repository_id,
    ('com.informatica.powercenter.process.'::text || replace((otype.object_type_name)::text, ' '::text, ''::text)) AS element_class_id,
    (((otype.object_type_name)::text || '_'::text) || ltrim(((tasks.task_id)::character varying)::text)) AS element_id,
    'GLOBAL'::text AS scope_type,
    tattr.attr_name AS elmnt_attr_name,
        CASE
            WHEN (((tattr.object_type_id = 71) AND (tattr.attr_id = ANY (ARRAY[12, 13, 14, 17, 18]))) OR ((tattr.object_type_id = 58) AND (tattr.attr_id = 1))) THEN (
            CASE
                WHEN (((tattrval.attr_value)::character varying)::text = '1'::text) THEN 'Yes'::text
                ELSE 'No'::text
            END)::character varying
            ELSE
            CASE
                WHEN ((tattr.object_type_id = 58) AND (tattr.attr_id = 2)) THEN (
                CASE (tattrval.attr_value)::character varying
                    WHEN '1'::text THEN 'Restart task'::text
                    WHEN '0'::text THEN 'Fail task and continue workflow'::text
                    ELSE NULL::text
                END)::character varying
                ELSE
                CASE
                    WHEN (tattr.object_type_id = 68) THEN
                    CASE
                        WHEN (tattr.attr_id = ANY (ARRAY[17, 109, 110, 111])) THEN (
                        CASE (tattrval.attr_value)::character varying
                            WHEN '1'::text THEN 'Yes'::text
                            ELSE 'No'::text
                        END)::character varying
                        ELSE
                        CASE
                            WHEN (tattr.attr_id = 107) THEN (
                            CASE (tattrval.attr_value)::character varying
                                WHEN '9'::text THEN 'To Source with View'::text
                                WHEN '11'::text THEN 'Full with View'::text
                                WHEN '1'::text THEN 'To Source'::text
                                WHEN '2'::text THEN 'To Target'::text
                                WHEN '3'::text THEN 'Full'::text
                                WHEN '4'::text THEN 'Configured at runtime'::text
                                WHEN '0'::text THEN 'None'::text
                                ELSE NULL::text
                            END)::character varying
                            ELSE
                            CASE
                                WHEN (tattr.attr_id = 18) THEN (
                                CASE (tattrval.attr_value)::character varying
                                    WHEN '2'::text THEN 'Restart Task'::text
                                    WHEN '1'::text THEN 'Resume from last checkpoint'::text
                                    WHEN '0'::text THEN 'Fail task & continue workflow'::text
                                    ELSE NULL::text
                                END)::character varying
                                ELSE tattrval.attr_value
                            END
                        END
                    END
                    ELSE tattrval.attr_value
                END
            END
        END AS elmnt_attr_value,
    ''::text AS elmnt_attr_desc,
    ''::text AS data_type,
    ''::text AS src_create_dt,
    tasks.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    tasks.subject_id
   FROM public.opb_task tasks,
    public.opb_object_type otype,
    public.opb_mmd_task_attr tattr,
    public.opb_task_attr tattrval
  WHERE ((tasks.task_type = otype.object_type_id) AND (tasks.is_reusable = 1) AND (tattrval.task_id = tasks.task_id) AND (tattrval.task_type = tasks.task_type) AND (tattrval.version_number = tasks.version_number) AND (tasks.is_visible = 1) AND (tattrval.workflow_id = 0) AND (tattrval.instance_id = 0) AND (tattrval.ref_session_id = 0) AND (tattrval.group_id = 0) AND (tattrval.attr_id = tattr.attr_id) AND (tattr.object_type_id = tasks.task_type))
UNION ALL
 SELECT ''::text AS repository_id,
    (('com.informatica.powercenter.process.'::text || replace((otype.object_type_name)::text, ' '::text, ''::text)) || 'TaskInstance'::text) AS element_class_id,
    ((('TASK_INSTANCE_'::text || (otype.object_type_name)::text) || '_'::text) || ltrim(((tinst.instance_id)::character varying)::text)) AS element_id,
    'GLOBAL'::text AS scope_type,
    tattr.attr_name AS elmnt_attr_name,
        CASE
            WHEN (((tattr.object_type_id = 71) AND (tattr.attr_id = ANY (ARRAY[12, 13, 14, 17, 18]))) OR ((tattr.object_type_id = 58) AND (tattr.attr_id = 1))) THEN (
            CASE
                WHEN (((tattrval.attr_value)::character varying)::text = '1'::text) THEN 'Yes'::text
                ELSE 'No'::text
            END)::character varying
            ELSE
            CASE
                WHEN ((tattr.object_type_id = 58) AND (tattr.attr_id = 2)) THEN (
                CASE (tattrval.attr_value)::character varying
                    WHEN '1'::text THEN 'Restart task'::text
                    WHEN '0'::text THEN 'Fail task and continue workflow'::text
                    ELSE NULL::text
                END)::character varying
                ELSE
                CASE
                    WHEN (tattr.object_type_id = 68) THEN
                    CASE
                        WHEN (tattr.attr_id = ANY (ARRAY[17, 109, 110, 111])) THEN (
                        CASE (tattrval.attr_value)::character varying
                            WHEN '1'::text THEN 'Yes'::text
                            ELSE 'No'::text
                        END)::character varying
                        ELSE
                        CASE
                            WHEN (tattr.attr_id = 107) THEN (
                            CASE (tattrval.attr_value)::character varying
                                WHEN '9'::text THEN 'To Source with View'::text
                                WHEN '11'::text THEN 'Full with View'::text
                                WHEN '1'::text THEN 'To Source'::text
                                WHEN '2'::text THEN 'To Target'::text
                                WHEN '3'::text THEN 'Full'::text
                                WHEN '4'::text THEN 'Configured at runtime'::text
                                WHEN '0'::text THEN 'None'::text
                                ELSE NULL::text
                            END)::character varying
                            ELSE
                            CASE
                                WHEN (tattr.attr_id = 18) THEN (
                                CASE (tattrval.attr_value)::character varying
                                    WHEN '2'::text THEN 'Restart Task'::text
                                    WHEN '1'::text THEN 'Resume from last checkpoint'::text
                                    WHEN '0'::text THEN 'Fail task & continue workflow'::text
                                    ELSE NULL::text
                                END)::character varying
                                ELSE tattrval.attr_value
                            END
                        END
                    END
                    ELSE tattrval.attr_value
                END
            END
        END AS elmnt_attr_value,
    ''::text AS elmnt_attr_desc,
    ''::text AS data_type,
    ''::text AS src_create_dt,
    tasks.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    tasks.subject_id
   FROM public.opb_task tasks,
    public.opb_object_type otype,
    public.opb_mmd_task_attr tattr,
    public.opb_task_attr tattrval,
    public.opb_task_inst tinst,
    public.opb_task wflow
  WHERE ((tinst.task_type = otype.object_type_id) AND (tattrval.task_id = tinst.task_id) AND (tinst.task_id = tasks.task_id) AND (tinst.task_type = tasks.task_type) AND (tasks.is_visible = 1) AND (tinst.workflow_id = wflow.task_id) AND ((wflow.task_type = 71) OR (wflow.task_type = 70)) AND (tinst.version_number = wflow.version_number) AND (wflow.is_visible = 1) AND (tattrval.task_type = tinst.task_type) AND (((tasks.is_reusable = 1) AND (tattrval.instance_id = tinst.instance_id) AND (tattrval.workflow_id = tinst.workflow_id) AND (tattrval.version_number = tinst.version_number)) OR ((tasks.is_reusable = 0) AND (tattrval.instance_id = 0) AND (tattrval.workflow_id = 0) AND (tattrval.version_number = tasks.version_number))) AND (tattrval.attr_id = tattr.attr_id) AND (tattr.object_type_id = tasks.task_type));


