--
-- Name: v_attribute_tgt; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_attribute_tgt AS
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.map.TargetDefinition'::text AS element_class_id,
    ('Target Definition_'::text || ltrim(((targ.target_id)::character varying)::text)) AS element_id,
    'GLOBAL'::text AS scope_type,
        CASE
            WHEN ((att.attr_name)::text = 'DTD Reference'::text) THEN 'DTD/Schema Reference'::character varying
            ELSE att.attr_name
        END AS elmnt_attr_name,
        CASE
            WHEN (att.attr_id = 17) THEN (
            CASE (attrval.attr_value)::character varying
                WHEN '1'::text THEN 'Append'::text
                WHEN '2'::text THEN 'Truncate'::text
                WHEN '0'::text THEN 'None'::text
                ELSE NULL::text
            END)::character varying
            ELSE
            CASE
                WHEN (att.attr_id = 18) THEN (
                CASE (attrval.attr_value)::character varying
                    WHEN '1'::text THEN 'Unix'::text
                    WHEN '2'::text THEN 'Windows'::text
                    WHEN '3'::text THEN 'None'::text
                    WHEN '0'::text THEN 'System Default'::text
                    ELSE NULL::text
                END)::character varying
                ELSE attrval.attr_value
            END
        END AS elmnt_attr_value,
    ''::text AS elmnt_attr_desc,
    ''::text AS data_type,
    ''::text AS src_create_dt,
    targ.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    targ.subj_id AS subject_id
   FROM public.opb_widget_attr attrval,
    public.opb_attr att,
    public.opb_targ targ
  WHERE ((targ.target_id = attrval.widget_id) AND (targ.version_number = attrval.version_number) AND (targ.is_visible = 1) AND (attrval.widget_type = 2) AND (att.attr_id = attrval.attr_id) AND (att.object_type_id = 2) AND (attrval.mapping_id = 0) AND (attrval.instance_id = 0) AND (attrval.session_id = 0) AND (attrval.partition_id = 0) AND (attrval.session_task_id = 0) AND (attrval.line_no = 1));


