--
-- Name: v_elmnt_wdgts; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_elmnt_wdgts AS
 SELECT ' '::text AS repository_id,
    ('com.informatica.powercenter.map.'::text || replace((otype.object_type_name)::text, ' '::text, ''::text)) AS class_id,
    (((otype.object_type_name)::text || '_'::text) || ltrim(((widg.widget_id)::character varying)::text)) AS element_id,
    widg.version_number AS version_num,
    widg.widget_name AS element_name,
    widg.widget_name AS element_label,
    ''::text AS element_alias,
    widg.comments AS element_desc,
    ''::text AS element_usage,
    'Application'::text AS element_type,
    otype.object_type_name AS element_subtype,
    'REUSABLE'::text AS element_attr1,
    'Yes'::text AS element_value1,
        CASE
            WHEN (map.is_valid IS NULL) THEN ''::text
            ELSE 'VALID'::text
        END AS element_attr2,
        CASE
            WHEN (map.is_valid IS NULL) THEN ''::text
            ELSE
            CASE
                WHEN (map.is_valid = 0) THEN 'No'::text
                ELSE 'Yes'::text
            END
        END AS element_value2,
    ''::text AS element_attr3,
    ''::text AS element_value3,
        CASE
            WHEN (map.is_valid = 0) THEN 'N'::text
            ELSE 'Y'::text
        END AS valid_flag,
    'N'::text AS disabled_flag,
    ''::text AS src_create_dt,
    widg.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    widg.subject_id
   FROM public.opb_object_type otype,
    (public.opb_widget widg
     LEFT JOIN public.opb_mapping map ON (((widg.widget_id = map.ref_widget_id) AND (map.is_visible = 1))))
  WHERE ((otype.object_type_id = widg.widget_type) AND (widg.is_reusable = 1) AND (widg.is_visible = 1));


