CREATE VIEW public.v_ime_part_sinst AS
 SELECT ' '::text AS repository_id,
    (('com.informatica.powercenter.process.'::text || replace((otype.object_type_name)::text, ' '::text, ''::text)) || 'Partition'::text) AS partition_class_id,
    (((((((((otype.object_type_name)::text || '_'::text) || 'Partition'::text) || '_'::text) || ltrim(((partdef.session_id)::character varying)::text)) || '_'::text) || ltrim(((partdef.sess_widg_inst_id)::character varying)::text)) || '_'::text) || ltrim(((partdef.partition_id)::character varying)::text)) AS partition_id,
    ((('TASK_INSTANCE_'::text || (otype.object_type_name)::text) || '_'::text) || ltrim(((tinst.instance_id)::character varying)::text)) AS task_id,
    (('com.informatica.powercenter.process.'::text || replace((otype.object_type_name)::text, ' '::text, ''::text)) || 'TaskInstance'::text) AS task_class_id,
        CASE
            WHEN (swinst.partition_type = 1) THEN 'Pass-Through'::text
            ELSE
            CASE
                WHEN (swinst.partition_type = 3) THEN 'Round-Robin'::text
                ELSE
                CASE
                    WHEN (swinst.partition_type = 4) THEN 'Key-Range'::text
                    ELSE
                    CASE
                        WHEN (swinst.partition_type = 5) THEN 'Hash-Key'::text
                        ELSE 'Other'::text
                    END
                END
            END
        END AS partition_type,
    partdef.partition_name,
    partdef.partition_name AS partition_desc,
    ''::text AS partition_text1,
    ''::text AS partition_text2,
    ''::text AS partition_text3,
    '1'::text AS version_num,
    partdef.last_saved AS src_create_dt,
    partdef.last_saved AS src_update_dt,
    ''::text AS eff_from_dt,
    ''::text AS eff_to_dt,
    tsk.subject_id
   FROM public.opb_object_type otype,
    public.opb_partition_def partdef,
    public.opb_task_inst tinst,
    public.opb_task tsk,
    public.opb_swidget_inst swinst,
    public.opb_task wkflow_or_wklet
  WHERE ((otype.object_type_id = 68) AND (otype.object_type_id = tinst.task_type) AND (partdef.session_id = tinst.task_id) AND (partdef.session_id = tsk.task_id) AND (partdef.version_number = tsk.version_number) AND (tsk.is_visible = 1) AND (tsk.task_type = 68) AND (tsk.is_reusable = 0) AND (tinst.task_id = tsk.task_id) AND (tinst.workflow_id = wkflow_or_wklet.task_id) AND (tinst.version_number = wkflow_or_wklet.version_number) AND (wkflow_or_wklet.task_type = ANY (ARRAY[70, 71])) AND (wkflow_or_wklet.is_visible = 1) AND (swinst.sess_widg_inst_id = partdef.sess_widg_inst_id) AND (swinst.session_id = partdef.session_id) AND (swinst.version_number = partdef.version_number));


