    public.opb_task task,
    public.opb_task wkflow_task
  WHERE ((otype.object_type_id = 29) AND (taskinst_log.workflow_run_id = wflow_run.workflow_run_id) AND (taskinst_log.workflow_id = workflow.workflow_id) AND (workflow.workflow_id = wkflow_task.task_id) AND (workflow.version_number = wkflow_task.version_number) AND (wkflow_task.task_type = 71) AND (wkflow_task.is_visible = 1) AND (otype1.object_type_id = 41) AND (otype2.object_type_id = 71) AND (otype3.object_type_id = 68) AND (otype4.object_type_id = 21) AND (taskinst_log.task_type = 68) AND (taskinst_log.task_id = sess.session_id) AND (taskinst_log.version_number = sess.version_number) AND (taskinst_log.workflow_id = sesstask_log.workflow_id) AND (taskinst_log.workflow_run_id = sesstask_log.workflow_run_id) AND (taskinst_log.worklet_run_id = sesstask_log.worklet_run_id) AND (taskinst_log.instance_id = sesstask_log.instance_id) AND (taskinst_log.task_id = task.task_id) AND (taskinst_log.version_number = task.version_number) AND (taskinst_log.fragment_id = ANY (ARRAY[1, '-1'::integer])) AND (task.is_visible = 1) AND (task.task_type = 68));


ALTER TABLE public.v_ime_task_log OWNER TO infa;

--
-- Name: v_lkp_flds_in_cond_extract; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_lkp_flds_in_cond_extract AS
 SELECT wdgt.widget_id,
    wdgtfld.field_name,
    wdgtfld.field_id,
    map.mapping_id,
    map.ref_widget_id,
    wdgtattr.instance_id AS map_instance_id,
    wdgtattr.attr_value AS expression,
    (map.last_saved)::timestamp without time zone AS map_update_date,
    (wdgt.last_saved)::timestamp without time zone AS widget_update_date,
    wdgt.subject_id
   FROM public.opb_widget wdgt,
    public.opb_widget_field wdgtfld,
    public.opb_widget_attr wdgtattr,
    public.opb_widget_inst wdgtinst,
    public.opb_mapping map
  WHERE ((wdgt.widget_id = wdgtfld.widget_id) AND (wdgt.widget_id = wdgtattr.widget_id) AND (wdgtattr.attr_id = 5) AND (wdgtattr.mapping_id = wdgtinst.mapping_id) AND (wdgtattr.instance_id = wdgtinst.instance_id) AND (wdgtattr.version_number = wdgtinst.version_number) AND (map.version_number = wdgtinst.version_number) AND (wdgt.version_number = wdgtfld.version_number) AND (wdgtinst.mapping_id = map.mapping_id) AND (wdgt.is_visible = 1) AND (map.is_visible = 1) AND (wdgtattr.line_no = 1) AND (wdgt.widget_type = 11) AND (wdgtfld.porttype = ANY (ARRAY[1, 3, 7])))
UNION ALL
 SELECT wdgt.widget_id,
    wdgtfld.field_name,
    wdgtfld.field_id,
    map.mapping_id,
    map.ref_widget_id,
    wdgtinst.instance_id AS map_instance_id,
    wdgtattr.attr_value AS expression,
    (map.last_saved)::timestamp without time zone AS map_update_date,
    (wdgt.last_saved)::timestamp without time zone AS widget_update_date,
    wdgt.subject_id
   FROM public.opb_widget wdgt,
    public.opb_widget_field wdgtfld,
    public.opb_widget_attr wdgtattr,
    public.opb_mapping map,
    public.opb_widget_inst wdgtinst
  WHERE ((wdgtinst.mapping_id = map.mapping_id) AND (wdgtinst.widget_id = wdgt.widget_id) AND (wdgt.widget_id = wdgtfld.widget_id) AND (wdgt.widget_id = wdgtattr.widget_id) AND (wdgt.is_visible = 1) AND (map.is_visible = 1) AND (wdgt.version_number = wdgtattr.version_number) AND (wdgtinst.version_number = map.version_number) AND (wdgt.version_number = wdgtfld.version_number) AND (wdgtattr.attr_id = 5) AND (wdgtattr.mapping_id = 0) AND (wdgt.widget_type = 11) AND (wdgtattr.line_no = 1) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_widget_attr wdgtattr1
          WHERE ((wdgtattr1.widget_id = wdgt.widget_id) AND (wdgtattr1.mapping_id = map.mapping_id) AND (wdgtinst.instance_id = wdgtattr1.instance_id) AND (wdgtattr1.attr_id = wdgtattr.attr_id))))) AND (wdgtfld.porttype = ANY (ARRAY[1, 3, 7])));


ALTER TABLE public.v_lkp_flds_in_cond_extract OWNER TO infa;

