--
-- Name: v_pc8x_expr_parse; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_pc8x_expr_parse AS
 SELECT winst.mapping_id,
    map.version_number AS mapping_vers_num,
    otype.object_type_name AS widget_type,
    winst.widget_id,
    widg.version_number AS widget_vers_num,
    winst.instance_id,
    winst.instance_name,
    wdgtfld.field_id,
    wdgtfld.field_name,
    expr.expression AS expr,
    2 AS transformation_type,
        CASE
            WHEN (expr.line_no IS NULL) THEN 1
            ELSE expr.line_no
        END AS line_num,
    map.ref_widget_id,
    ('PC_'::text || (repo.reposit_name)::text) AS repository_id,
    (map.last_saved)::timestamp without time zone AS map_update_dt,
    NULL::timestamp without time zone AS eff_from_dt,
    NULL::timestamp without time zone AS eff_to_dt,
    map.subject_id AS trfn_subject_id,
    widg.subject_id AS tgt_subject_id
   FROM public.opb_reposit repo,
    public.opb_object_type otype,
    public.opb_mapping map,
    public.opb_widget_field wdgtfld,
    public.opb_widget_inst winst,
    public.opb_widget widg,
    (public.opb_widget_expr wexpr
     LEFT JOIN public.opb_expression expr ON (((wexpr.expr_id = expr.expr_id) AND (wexpr.version_number = expr.version_number))))
  WHERE ((repo.recid = 1) AND (winst.widget_type = ANY (ARRAY[9, 26, 5])) AND (winst.widget_id = wexpr.widget_id) AND (wdgtfld.field_id = wexpr.output_field_id) AND (wdgtfld.version_number = wexpr.version_number) AND (map.mapping_id = winst.mapping_id) AND (map.version_number = winst.version_number) AND (map.is_visible = 1) AND (wdgtfld.widget_id = winst.widget_id) AND (wdgtfld.widget_id = widg.widget_id) AND (wdgtfld.version_number = widg.version_number) AND (widg.is_visible = 1) AND (wdgtfld.porttype = ANY (ARRAY[2, 32])) AND (otype.object_type_id = winst.widget_type))
UNION ALL
 SELECT winst.mapping_id,
    map.version_number AS mapping_vers_num,
    otype.object_type_name AS widget_type,
    winst.widget_id,
    widg.version_number AS widget_vers_num,
    winst.instance_id,
    winst.instance_name,
    wdgtfld.field_id,
    wdgtfld.field_name,
    NULL::character varying AS expr,
        CASE
            WHEN (winst.widget_type = ANY (ARRAY[11, 6, 8])) THEN 1
            ELSE 2
        END AS transformation_type,
    1 AS line_num,
    map.ref_widget_id,
    ('PC_'::text || (repo.reposit_name)::text) AS repository_id,
    (map.last_saved)::timestamp without time zone AS map_update_dt,
    NULL::timestamp without time zone AS eff_from_dt,
    NULL::timestamp without time zone AS eff_to_dt,
    map.subject_id AS trfn_subject_id,
    widg.subject_id AS tgt_subject_id
   FROM public.opb_reposit repo,
    public.opb_object_type otype,
    public.opb_widget_field wdgtfld,
    public.opb_mapping map,
    public.opb_widget_inst winst,
    public.opb_widget widg
  WHERE ((repo.recid = 1) AND (((winst.widget_type = ANY (ARRAY[11, 6, 8])) AND (wdgtfld.porttype = ANY (ARRAY[6, 7, 14]))) OR ((winst.widget_type = ANY (ARRAY[9, 26, 5])) AND (wdgtfld.porttype <> ALL (ARRAY[2, 32])))) AND (map.mapping_id = winst.mapping_id) AND (map.version_number = winst.version_number) AND (map.is_visible = 1) AND (wdgtfld.widget_id = winst.widget_id) AND (wdgtfld.widget_id = widg.widget_id) AND (wdgtfld.version_number = widg.version_number) AND (widg.is_visible = 1) AND (otype.object_type_id = winst.widget_type));


ALTER TABLE public.v_pc8x_expr_parse OWNER TO infa;

