        CASE
            WHEN (map.ref_widget_id = 0) THEN ('Mapping_'::text || ((widgdep.mapping_id)::character varying)::text)
            ELSE ('Mapplet_'::text || ((map.ref_widget_id)::character varying)::text)
        END AS transform_id,
        CASE
            WHEN (map.ref_widget_id = 0) THEN 'com.informatica.powercenter.map.Mapping'::text
            ELSE 'com.informatica.powercenter.map.Mapplet'::text
        END AS transform_class_id,
    'Default_Expression'::text AS map_id,
    'com.informatica.powercenter.map.MapExpression'::text AS map_class_id,
    'Default_FieldExpression'::text AS feature_map_id,
    'com.informatica.powercenter.map.MapExpression'::text AS feat_map_class_id,
    ((((('WIDGET_INSTANCE_'::text || (( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = src_winst.widget_type)))::text) || '_'::text) || ((src_winst.mapping_id)::character varying)::text) || '_'::text) || ((src_winst.instance_id)::character varying)::text) AS source_id,
    (('com.informatica.powercenter.map.'::text || replace(replace((( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = src_winst.widget_type)))::text, ' '::text, ''::text), '-'::text, ''::text)) || 'Instance'::text) AS source_class_id,
    ' '::text AS source_repo_id,
    ((((((( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = src_winst.widget_type)))::text || '_'::text) || 'Field_'::text) || ltrim(((src_winst.widget_id)::character varying)::text)) || '_'::text) || ltrim(((widgdep.from_field_id)::character varying)::text)) AS src_feature_id,
    (('com.informatica.powercenter.map.'::text || replace(replace((( SELECT otype.object_type_name
           FROM public.opb_object_type otype
