    NULL::text AS source_name,
    NULL::text AS source_schema_name,
    NULL::text AS src_feature_name,
    ((((('WIDGET_INSTANCE_'::text || (( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = tgt_winst.widget_type)))::text) || '_'::text) || ((tgt_winst.mapping_id)::character varying)::text) || '_'::text) || ((tgt_winst.instance_id)::character varying)::text) AS target_id,
    (('com.informatica.powercenter.map.'::text || replace(replace((( SELECT otype.object_type_name
