    ' '::text AS target_repo_id,
    ((((((( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = tgt_winst.widget_type)))::text || '_'::text) || 'Field_'::text) || ltrim(((tgt_winst.widget_id)::character varying)::text)) || '_'::text) || ltrim(((widgdep.to_field_id)::character varying)::text)) AS tgt_feature_id,
    (('com.informatica.powercenter.map.'::text || replace(replace((( SELECT otype.object_type_name
           FROM public.opb_object_type otype
          WHERE (otype.object_type = tgt_winst.widget_type)))::text, ' '::text, ''::text), '-'::text, ''::text)) || 'Port'::text) AS tgt_feat_class_id,
    NULL::text AS tgt_connection_id,
