  WHERE ((widgdep.from_instance_id = src_winst.instance_id) AND (widgdep.mapping_id = src_winst.mapping_id) AND (widgdep.version_number = src_winst.version_number) AND (src_winst.widget_id = src.widget_id) AND (src_winst.widget_type = src.widget_type) AND (src.is_visible = 1) AND (widgdep.to_instance_id = tgt_winst.instance_id) AND (widgdep.mapping_id = tgt_winst.mapping_id) AND (widgdep.version_number = tgt_winst.version_number) AND (tgt_winst.widget_id = tgt.widget_id) AND (tgt_winst.widget_type = tgt.widget_type) AND (tgt.is_visible = 1) AND (widgdep.mapping_id = map.mapping_id) AND (widgdep.version_number = map.version_number) AND (map.is_visible = 1))
