    (('com.informatica.powercenter.map.'::text || replace(replace((otype.object_type_name)::text, ' '::text, ''::text), '-'::text, ''::text)) || 'Port'::text) AS tgt_feat_class_id,
    NULL::text AS tgt_connection_id,
    NULL::text AS tgt_conn_class_id,
    NULL::text AS target_name,
    NULL::text AS target_schema_name,
