  WHERE ((winst.widget_id = wgt.widget_id) AND (winst.widget_type = wgt.widget_type) AND (wgt.widget_id = wgt_fld.widget_id) AND (wgt.version_number = wgt_fld.version_number) AND (wgt.is_visible = 1) AND (winst1.widget_id = wgt1.widget_id) AND (winst1.widget_type = wgt1.widget_type) AND (wgt1.widget_id = wgt_fld1.widget_id) AND (wgt1.version_number = wgt_fld1.version_number) AND (wgt1.is_visible = 1) AND (winst.widget_type = 56) AND (winst.widget_prop = winst1.instance_id) AND (winst.mapping_id = winst1.mapping_id) AND (winst.version_number = winst1.version_number) AND (winst1.widget_type = otype.object_type_id) AND (winst.mapping_id = map.mapping_id) AND (winst.version_number = map.version_number) AND ((wgt_fld.field_name)::text = 'MsgId'::text) AND (map.is_visible = 1));


