--
-- Name: v_pc8x_ff_fields; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_pc8x_ff_fields AS
 SELECT src.src_id AS widget_id,
    src.version_number,
    srcfld.fldid,
    srcfld.src_name AS field_name,
    srcfld.fldno AS field_order,
    picdsc.src_prec,
    picdsc.src_scale,
    ( SELECT min((dtype.dtype_name)::text) AS min
           FROM public.rep_fld_datatype dtype
          WHERE ((picdsc.src_type = dtype.dtype_num) OR (picdsc.src_ntype = dtype.dtype_num))) AS dtype_name,
    picdsc.src_ntype AS dtype_num,
    1 AS widget_type,
    src.subj_id AS subject_id
   FROM public.opb_src src,
    public.opb_src_fld srcfld,
    public.opb_dbd dbd,
    public.opb_picdsc picdsc
  WHERE ((src.src_id = srcfld.src_id) AND (src.version_number = srcfld.version_number) AND (src.is_visible = 1) AND (srcfld.picid = picdsc.picid) AND (dbd.dbdid = src.dbdid) AND (dbd.version_number = src.version_number) AND (dbd.dbtype <> ALL (ARRAY[12, 0])) AND (srcfld.version_number = picdsc.version_number) AND (EXISTS ( SELECT 'X'::text
           FROM public.opb_sess_file_ref,
            public.opb_swidget_inst
          WHERE ((opb_sess_file_ref.session_id = opb_swidget_inst.session_id) AND (opb_sess_file_ref.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (src.src_id = opb_swidget_inst.widget_id) AND (opb_swidget_inst.widget_type = 1)))))
UNION ALL
 SELECT targ.target_id AS widget_id,
    targ.version_number,
    targfld.fldid,
    targfld.target_name AS field_name,
    targfld.fldno AS field_order,
    targfld.dprec AS src_prec,
    targfld.dscale AS src_scale,
    ( SELECT min((dtype.dtype_name)::text) AS min
           FROM public.rep_fld_datatype dtype
          WHERE ((targfld.dtype = dtype.dtype_num) OR (targfld.ndtype = dtype.dtype_num))) AS dtype_name,
    targfld.dtype AS dtype_num,
    2 AS widget_type,
    targ.subj_id AS subject_id
   FROM public.opb_targ targ,
    public.opb_targ_fld targfld
  WHERE ((targ.target_id = targfld.target_id) AND (targ.version_number = targfld.version_number) AND (targ.is_visible = 1) AND (targ.dbtype <> 12) AND (EXISTS ( SELECT 'X'::text
           FROM public.opb_sess_file_ref,
            public.opb_swidget_inst
          WHERE ((opb_sess_file_ref.session_id = opb_swidget_inst.session_id) AND (opb_sess_file_ref.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (targ.target_id = opb_swidget_inst.widget_id) AND (opb_swidget_inst.widget_type = 2)))))
UNION ALL
 SELECT wgt.widget_id,
    wgt.version_number,
    wfld.field_id AS fldid,
    wfld.field_name,
    wfld.field_order,
    wfld.wgt_prec AS src_prec,
    wfld.wgt_scale AS src_scale,
    dtype.dtype_name,
    dtype.dtype_num,
    11 AS widget_type,
    wgt.subject_id
   FROM public.opb_widget wgt,
    public.opb_widget_field wfld,
    public.rep_fld_datatype dtype,
    public.opb_widget_attr wattr
  WHERE ((wgt.widget_id = wfld.widget_id) AND (wgt.version_number = wfld.version_number) AND (wgt.is_visible = 1) AND (wgt.widget_type = 11) AND (wfld.wgt_datatype = dtype.dtype_num) AND (wattr.widget_id = wgt.widget_id) AND (wattr.widget_type = wgt.widget_type) AND (wattr.version_number = wgt.version_number) AND (wattr.attr_id = 7) AND ((wattr.attr_value)::text = '2'::text) AND (EXISTS ( SELECT 'X'::text
           FROM public.opb_sess_file_ref,
            public.opb_swidget_inst
          WHERE ((opb_sess_file_ref.session_id = opb_swidget_inst.session_id) AND (opb_sess_file_ref.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (wgt.widget_id = opb_swidget_inst.widget_id) AND (opb_swidget_inst.widget_type = wgt.widget_type)))) AND (wfld.porttype = ANY (ARRAY[8, 10, 14, 2050])));


