  WHERE ((tinst.workflow_id = wflow.task_id) AND (tinst.version_number = wflow.version_number) AND (wflow.is_visible = 1) AND (opb_swidget_inst.mapping_id = opb_mapping.mapping_id) AND (opb_mapping.is_visible = 1) AND (tinst.task_id = opb_sess_file_ref.session_id) AND (task.task_id = opb_swidget_inst.session_id) AND (task.version_number = opb_swidget_inst.version_number) AND (task.is_visible = 1) AND (opb_sess_file_ref.session_id = opb_swidget_inst.session_id) AND (opb_sess_file_ref.version_number = opb_swidget_inst.version_number) AND (opb_sess_file_ref.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (opb_swidget_inst.widget_id = wgt.widget_id) AND (opb_swidget_inst.widget_type = wgt.widget_type) AND (opb_swidget_inst.widget_type = 11) AND (wgt.is_visible = 1) AND (wattr.widget_id = wgt.widget_id) AND (wattr.version_number = wgt.version_number) AND (wattr.attr_id = 7) AND ((wattr.attr_value)::text = '2'::text) AND (xattr.session_inst_id = tinst.instance_id) AND (xattr.session_id = opb_swidget_inst.session_id) AND (xattr.version_number = tinst.version_number) AND (xattr.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (xattr.object_type = 103) AND (xattr.attr_id = 1) AND (xattr.partition_id = xattr2.partition_id) AND (xattr2.session_inst_id = tinst.instance_id) AND (xattr2.session_id = opb_swidget_inst.session_id) AND (xattr2.version_number = tinst.version_number) AND (xattr2.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (xattr2.object_type = 103) AND (xattr2.attr_id = 2) AND (xattr2.attr_value IS NOT NULL));


ALTER TABLE public.v_pc8x_ff_objects OWNER TO infa;

--
-- Name: v_pc8x_file_type; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_pc8x_file_type AS
 SELECT
        CASE
            WHEN ((opb_extn_attr.attr_value)::text = '0'::text) THEN 'Direct'::text
            ELSE 'Indirect'::text
        END AS src_file_type,
    opb_sess_file_ref.file_id,
    opb_task_inst.instance_id,
    opb_extn_attr.partition_id
   FROM public.opb_extn_attr,
    public.opb_sess_file_ref,
    public.opb_task_inst,
    public.opb_task
  WHERE ((opb_task.task_id = opb_extn_attr.session_id) AND (opb_task.is_visible = 1) AND (opb_extn_attr.session_inst_id = 0) AND (opb_task.version_number = opb_extn_attr.version_number) AND (opb_sess_file_ref.session_id = opb_extn_attr.session_id) AND (opb_sess_file_ref.version_number = opb_extn_attr.version_number) AND (opb_sess_file_ref.sess_widg_inst_id = opb_extn_attr.sess_widg_inst_id) AND (opb_extn_attr.object_type = ANY (ARRAY[78, 103])) AND (opb_extn_attr.attr_id = 3) AND (opb_task.task_id = opb_task_inst.task_id) AND (EXISTS ( SELECT 'X'::text
           FROM public.opb_task wflow
          WHERE ((opb_task_inst.workflow_id = wflow.task_id) AND (wflow.is_visible = 1) AND (wflow.version_number = opb_task_inst.version_number)))) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_extn_attr a
          WHERE ((a.session_inst_id = opb_task_inst.instance_id) AND (a.version_number = opb_task_inst.version_number) AND (a.object_type = ANY (ARRAY[78, 103])) AND (a.attr_id = 3) AND (opb_sess_file_ref.sess_widg_inst_id = a.sess_widg_inst_id))))))
UNION ALL
 SELECT
        CASE
            WHEN ((opb_extn_attr.attr_value)::text = '0'::text) THEN 'Direct'::text
            ELSE 'Indirect'::text
        END AS src_file_type,
    opb_sess_file_ref.file_id,
    opb_task_inst.instance_id,
    opb_extn_attr.partition_id
   FROM public.opb_extn_attr,
    public.opb_sess_file_ref,
    public.opb_task_inst,
    public.opb_task
  WHERE ((opb_task.task_id = opb_extn_attr.session_id) AND (opb_task.is_visible = 1) AND (opb_sess_file_ref.session_id = opb_extn_attr.session_id) AND (opb_sess_file_ref.version_number = opb_extn_attr.version_number) AND (opb_sess_file_ref.sess_widg_inst_id = opb_extn_attr.sess_widg_inst_id) AND (opb_extn_attr.object_type = ANY (ARRAY[78, 103])) AND (opb_extn_attr.attr_id = 3) AND (opb_extn_attr.session_inst_id = opb_task_inst.instance_id) AND (opb_task_inst.version_number = opb_extn_attr.version_number));


