--

CREATE VIEW public.v_pc8x_lkp_sess_inst_cnx AS
 SELECT opb_swidget_inst.sess_widg_inst_id AS session_widg_inst_id,
    opb_sess_cnx_refs.session_inst_id,
    opb_sess_cnx_refs.session_id,
    opb_swidget_inst.version_number,
    opb_swidget_inst.mapping_id AS orig_mapping_id,
        CASE
            WHEN (opb_swidget_inst.mapplet_map_id = 0) THEN opb_swidget_inst.mapping_id
            ELSE opb_swidget_inst.mapplet_map_id
        END AS mapping_id,
    opb_swidget_inst.instance_id AS map_instance_id,
    (opb_swidget_inst.instance_id & 65535) AS instance_id,
    opb_swidget_inst.widget_id,
    opb_sess_cnx_refs.ref_object_value,
    opb_sess_cnx_refs.ref_object_id,
    opb_widget.subject_id
   FROM public.opb_sess_cnx_refs,
    public.opb_task wflow,
    public.opb_task sess,
    public.opb_swidget_inst,
    public.opb_widget
  WHERE ((opb_sess_cnx_refs.session_inst_id <> 0) AND (wflow.task_id = opb_sess_cnx_refs.workflow_id) AND (wflow.version_number = opb_sess_cnx_refs.version_number) AND (wflow.is_visible = 1) AND (sess.task_id = opb_swidget_inst.session_id) AND (sess.version_number = opb_swidget_inst.version_number) AND (sess.is_visible = 1) AND (opb_sess_cnx_refs.session_id = opb_swidget_inst.session_id) AND (opb_sess_cnx_refs.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (opb_swidget_inst.widget_type = 11) AND (opb_swidget_inst.widget_id = opb_widget.widget_id) AND (opb_widget.is_visible = 1))
UNION ALL
 SELECT opb_swidget_inst.sess_widg_inst_id AS session_widg_inst_id,
    tinst.instance_id AS session_inst_id,
    opb_sess_cnx_refs.session_id,
    opb_swidget_inst.version_number,
    opb_swidget_inst.mapping_id AS orig_mapping_id,
        CASE
            WHEN (opb_swidget_inst.mapplet_map_id = 0) THEN opb_swidget_inst.mapping_id
            ELSE opb_swidget_inst.mapplet_map_id
        END AS mapping_id,
    opb_swidget_inst.instance_id AS map_instance_id,
    (opb_swidget_inst.instance_id & 65535) AS instance_id,
    opb_swidget_inst.widget_id,
    opb_sess_cnx_refs.ref_object_value,
    opb_sess_cnx_refs.ref_object_id,
    opb_widget.subject_id
   FROM public.opb_sess_cnx_refs,
    public.opb_task wflow,
    public.opb_task_inst tinst,
    public.opb_task sess,
    public.opb_swidget_inst,
    public.opb_widget
  WHERE ((opb_sess_cnx_refs.session_inst_id = 0) AND (opb_sess_cnx_refs.workflow_id = 0) AND (sess.task_id = opb_swidget_inst.session_id) AND (sess.version_number = opb_swidget_inst.version_number) AND (sess.is_visible = 1) AND (sess.task_id = tinst.task_id) AND (wflow.task_id = tinst.workflow_id) AND (wflow.version_number = tinst.version_number) AND (wflow.is_visible = 1) AND (opb_sess_cnx_refs.version_number = opb_swidget_inst.version_number) AND (opb_sess_cnx_refs.session_id = opb_swidget_inst.session_id) AND (opb_sess_cnx_refs.sess_widg_inst_id = opb_swidget_inst.sess_widg_inst_id) AND (opb_swidget_inst.widget_type = 11) AND (opb_swidget_inst.widget_id = opb_widget.widget_id) AND (opb_widget.is_visible = 1) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_sess_cnx_refs b
          WHERE ((b.session_inst_id = tinst.instance_id) AND (b.session_id = opb_sess_cnx_refs.session_id) AND (b.sess_widg_inst_id = opb_sess_cnx_refs.sess_widg_inst_id))))));


