--
-- Name: v_pc8x_master_expression; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_pc8x_master_expression AS
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.map.MapExpression'::text AS class_id,
    (((((otype.object_type_name)::text || '_Field_'::text) || ((wdgtfld.widget_id)::character varying)::text) || '_'::text) || ((wdgtfld.field_id)::character varying)::text) AS expression_id,
    'SQL'::text AS language,
    expr.expression AS expression_text,
    ''::text AS expression_text1,
    ''::text AS expression_text2,
    ''::text AS expression_text3,
    NULL::timestamp without time zone AS src_create_dt,
    (wdgt.last_saved)::timestamp without time zone AS src_update_dt,
    NULL::timestamp without time zone AS eff_from_dt,
    NULL::timestamp without time zone AS eff_to_dt,
    wdgt.subject_id
   FROM public.opb_object_type otype,
    public.opb_expression expr,
    public.opb_widget_expr wexpr,
    public.opb_widget_field wdgtfld,
    public.opb_widget wdgt
  WHERE ((wdgt.widget_type = ANY (ARRAY[9, 26, 5])) AND (wdgt.widget_type = otype.object_type_id) AND (wdgt.widget_id = wdgtfld.widget_id) AND (wdgt.version_number = wdgtfld.version_number) AND (wdgtfld.widget_id = wexpr.widget_id) AND (wdgtfld.version_number = wexpr.version_number) AND (wdgtfld.field_id = wexpr.output_field_id) AND (wexpr.expr_id = expr.expr_id) AND (wexpr.version_number = expr.version_number) AND (expr.line_no = 1) AND (wdgtfld.porttype = ANY (ARRAY[2, 32])) AND (wdgt.is_visible = 1))
UNION ALL
 SELECT ' '::text AS repository_id,
    'com.informatica.powercenter.map.MapExpression'::text AS class_id,
    (((((otype.object_type_name)::text || '_'::text) || ((map.mapping_id)::character varying)::text) || '_'::text) || ((wdgtinst.instance_id)::character varying)::text) AS expression_id,
