--
-- Name: v_pc8x_sess_cnx_val; Type: VIEW; Schema: public; Owner: infa
--

CREATE VIEW public.v_pc8x_sess_cnx_val AS
 SELECT tinst.instance_id AS task_instance_id,
    tinst.task_id,
    tsk.version_number AS task_vers_num,
    tattr.attr_id,
    ltrim(rtrim((tattr.attr_value)::text)) AS attr_value,
    wflow.subject_id
   FROM public.opb_task_attr tattr,
    public.opb_task_inst tinst,
    public.opb_task tsk,
    public.opb_task wflow
  WHERE ((tinst.workflow_id = tattr.workflow_id) AND (tinst.task_id = tattr.task_id) AND (tinst.task_type = tattr.task_type) AND (tinst.instance_id = tattr.instance_id) AND (tinst.version_number = tattr.version_number) AND (tattr.attr_id = ANY (ARRAY[7, 8])) AND (tinst.task_id = tsk.task_id) AND (tsk.is_visible = 1) AND (wflow.task_id = tinst.workflow_id) AND (wflow.version_number = tinst.version_number) AND (wflow.is_visible = 1) AND (tattr.attr_value IS NOT NULL))
UNION ALL
 SELECT tinst.instance_id AS task_instance_id,
    tinst.task_id,
    tsk.version_number AS task_vers_num,
    tattr.attr_id,
    ltrim(rtrim((tattr.attr_value)::text)) AS attr_value,
    wflow.subject_id
   FROM public.opb_task_attr tattr,
    public.opb_task_inst tinst,
    public.opb_task wflow,
    public.opb_task tsk
  WHERE ((tattr.workflow_id = 0) AND (tinst.task_id = tattr.task_id) AND (tinst.task_type = tattr.task_type) AND (tinst.task_id = tsk.task_id) AND (tsk.is_visible = 1) AND (tsk.version_number = tattr.version_number) AND (tinst.workflow_id = wflow.task_id) AND (tinst.version_number = wflow.version_number) AND (wflow.is_visible = 1) AND (tattr.instance_id = 0) AND (tattr.attr_id = ANY (ARRAY[7, 8])) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_task_attr tattr1
          WHERE ((tinst.workflow_id = tattr1.workflow_id) AND (tinst.version_number = tattr1.version_number) AND (tinst.task_id = tattr1.task_id) AND (tinst.instance_id = tattr1.instance_id) AND (tattr1.attr_id = ANY (ARRAY[7, 8])))))) AND (tattr.attr_value IS NOT NULL));


