    swinst.mapping_id AS orig_mapping_id,
    swinst.mapplet_map_id AS mapping_id,
    swinst.instance_id AS map_instance_id,
        CASE
            WHEN (swinst.mapplet_inst_name IS NOT NULL) THEN swinst.mapplet_inst_name
            ELSE map.mapping_name
        END AS map_context_name,
    winst.instance_id,
    winst.widget_id,
    winst.widget_type,
    cnxref.ref_object_id AS connection_id,
    (tsk.last_saved)::timestamp without time zone AS task_update_dt,
    (wfvar.last_saved)::timestamp without time zone AS act_update_dt,
    NULL::timestamp without time zone AS eff_from_dt,
    NULL::timestamp without time zone AS eff_to_dt,
    tsk.subject_id AS task_subject_id,
    map.subject_id AS trfn_subject_id
   FROM public.opb_swidget_inst swinst,
    public.opb_mapping map,
    public.opb_widget_inst winst,
    public.opb_sess_cnx_refs cnxref,
    public.opb_task tsk,
    public.opb_wflow_var wfvar,
    public.opb_task_inst tinst,
    public.opb_task wflow
  WHERE ((swinst.widget_type = ANY (ARRAY[3, 45])) AND (wfvar.subject_id = tsk.subject_id) AND (tinst.task_id = tsk.task_id) AND (tsk.is_visible = 1) AND (tinst.task_id = swinst.session_id) AND (tinst.workflow_id = wfvar.workflow_id) AND ((tinst.instance_name)::text = (wfvar.task_inst_name)::text) AND ((wfvar.var_name)::text = 'Status'::text) AND (wfvar.version_number = tinst.version_number) AND (wfvar.version_number = wflow.version_number) AND (wfvar.workflow_id = wflow.task_id) AND (wflow.task_type = ANY (ARRAY[70, 71])) AND (wflow.is_visible = 1) AND (cnxref.ref_object_id <> 0) AND (cnxref.session_id = swinst.session_id) AND (cnxref.session_inst_id = tinst.instance_id) AND (cnxref.sess_widg_inst_id = swinst.sess_widg_inst_id) AND (cnxref.version_number = swinst.version_number) AND (cnxref.version_number = tsk.version_number) AND (swinst.mapplet_map_id = winst.mapping_id) AND (map.mapping_id = winst.mapping_id) AND (map.version_number = winst.version_number) AND (map.is_visible = 1) AND ((swinst.instance_id & 65535) = winst.instance_id))
UNION ALL
 SELECT swinst.session_id,
    swinst.sess_widg_inst_id AS session_widg_inst_id,
    tinst.instance_id AS task_inst_id,
    tinst.task_id,
    tsk.version_number AS task_vers_num,
