    public.opb_task tsk,
    public.opb_wflow_var wfvar,
    public.opb_task_inst tinst,
    public.opb_task wflow
  WHERE ((swinst.widget_type = ANY (ARRAY[3, 45])) AND (wfvar.subject_id = tsk.subject_id) AND (tinst.task_id = tsk.task_id) AND (tsk.is_visible = 1) AND (tinst.task_id = swinst.session_id) AND (tinst.workflow_id = wfvar.workflow_id) AND ((tinst.instance_name)::text = (wfvar.task_inst_name)::text) AND ((wfvar.var_name)::text = 'Status'::text) AND (wfvar.version_number = tinst.version_number) AND (wfvar.workflow_id = wflow.task_id) AND (wfvar.version_number = wflow.version_number) AND (wflow.task_type = ANY (ARRAY[70, 71])) AND (wflow.is_visible = 1) AND (cnxref.ref_object_id <> 0) AND (cnxref.session_id = swinst.session_id) AND (cnxref.session_inst_id = 0) AND (cnxref.sess_widg_inst_id = swinst.sess_widg_inst_id) AND (cnxref.version_number = swinst.version_number) AND (cnxref.version_number = tsk.version_number) AND (swinst.mapplet_map_id = winst.mapping_id) AND (map.mapping_id = winst.mapping_id) AND (map.version_number = winst.version_number) AND (map.is_visible = 1) AND ((swinst.instance_id & 65535) = winst.instance_id) AND (NOT (EXISTS ( SELECT 'X'::text
           FROM public.opb_sess_cnx_refs cnxref2
          WHERE ((cnxref2.session_id = tinst.task_id) AND (cnxref2.session_inst_id = tinst.instance_id) AND (cnxref2.sess_widg_inst_id = swinst.sess_widg_inst_id) AND (cnxref2.version_number = swinst.version_number))))))
UNION ALL
 SELECT swinst.session_id,
    swinst.sess_widg_inst_id AS session_widg_inst_id,
